import { getDoc } from "firebase/firestore";
import { paths, ANALYSIS_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runWebsiteDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // 1. analyses/website
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.website));
    if (!snap.exists()) {
      results.push({ id: "web-analysis", label: "analyses/website", status: "fail", detail: "문서 없음" });
    } else {
      const d = snap.data() as any;
      results.push({ id: "web-analysis", label: "analyses/website", status: "pass", detail: `writtenBy: ${d?.writtenBy ?? "N/A"}` });
    }
  } catch (err: any) {
    results.push({ id: "web-analysis", label: "analyses/website", status: "fail", detail: err.message });
  }

  // 2. analyses/seo-audit
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.seoAudit));
    results.push({ id: "web-seo", label: "analyses/seo-audit", status: snap.exists() ? "pass" : "warn", detail: snap.exists() ? "존재" : "문서 없음 (선택적)" });
  } catch (err: any) {
    results.push({ id: "web-seo", label: "analyses/seo-audit", status: "fail", detail: err.message });
  }

  // 3. raw/v1/lighthouse (desktop)
  try {
    const snap = await getDoc(paths.rawLighthouse(boardId, "desktop"));
    results.push({ id: "web-lh-desk", label: "raw/v1/lighthouse/desktop", status: snap.exists() ? "pass" : "warn", detail: snap.exists() ? "존재" : "문서 없음 (선택적)" });
  } catch (err: any) {
    results.push({ id: "web-lh-desk", label: "raw/v1/lighthouse/desktop", status: "fail", detail: err.message });
  }

  return results;
};
