import { useState } from "react";
import { Mail, LogOut, ShieldAlert } from "lucide-react";
import { useAuth } from "../contexts/AuthContext";

export function PendingApprovalGate() {
  const { user, signOut } = useAuth();
  const [isSigningOut, setIsSigningOut] = useState(false);

  const handleSignOut = async () => {
    setIsSigningOut(true);
    try {
      await signOut();
    } finally {
      setIsSigningOut(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-[var(--shell-main)] p-4 text-[var(--shell-text)]">
      <div className="w-full max-w-md">
        <div className="shell-panel rounded-[28px] p-8 text-center">
          <div className="mx-auto mb-6 grid h-16 w-16 place-items-center rounded-2xl bg-[var(--shell-accent-soft)] text-[var(--shell-accent)]">
            <ShieldAlert className="h-8 w-8" />
          </div>

          <h1 className="text-2xl font-semibold tracking-[-0.03em]">
            관리자 승인이 필요합니다
          </h1>
          <p className="mt-3 text-sm leading-[1.6] text-[var(--shell-text-muted)]">
            이 계정은 아직 승인되지 않았습니다.
            <br />
            관리자에게 권한을 요청하세요.
          </p>

          {user?.email && (
            <div className="mt-6 flex items-center justify-center gap-2 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3 text-sm text-[var(--shell-text-muted)]">
              <Mail className="h-4 w-4 shrink-0" />
              <span className="truncate">{user.email}</span>
            </div>
          )}

          <button
            onClick={handleSignOut}
            disabled={isSigningOut}
            className="shell-transition mt-6 flex w-full items-center justify-center gap-2 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3 text-sm font-medium hover:border-[var(--shell-accent)] hover:bg-[var(--shell-accent-soft)] disabled:cursor-not-allowed disabled:opacity-50"
          >
            <LogOut className="h-4 w-4" />
            <span>{isSigningOut ? "로그아웃 중..." : "로그아웃"}</span>
          </button>
        </div>
      </div>
    </div>
  );
}
