import { useState } from "react";
import { useParams } from "react-router-dom";
import { useDiagnosis } from "./dataHub";
import { HeaderV4DiagnosticButton } from "./V4DiagnosticPanel";
import { runDiagnosisDiagnostics } from "./diagnostics/diagnosisDiagnostics";
import { LazyStorageText } from "./components/LazyStorageText";

const categoryPillColor: Record<string, string> = {
  탐색: "border border-sky-400/40 bg-sky-500/15 text-sky-300 shell-badge-sky",
  "비교·검토": "border border-amber-400/40 bg-amber-500/15 text-amber-300 shell-badge-amber",
  선택: "border border-emerald-400/40 bg-emerald-500/15 text-emerald-300 shell-badge-emerald",
  "추천·확산": "border border-fuchsia-400/40 bg-fuchsia-500/15 text-fuchsia-300 shell-badge-fuchsia",
  DISCOVER: "border border-sky-400/40 bg-sky-500/15 text-sky-300 shell-badge-sky",
  CONSIDER: "border border-amber-400/40 bg-amber-500/15 text-amber-300 shell-badge-amber",
  DECIDE: "border border-emerald-400/40 bg-emerald-500/15 text-emerald-300 shell-badge-emerald",
  ADVOCATE: "border border-fuchsia-400/40 bg-fuchsia-500/15 text-fuchsia-300 shell-badge-fuchsia",
};

const diagCardMeta: Record<string, { border: string; headColor: string }> = {
  status: { border: "border-rose-400/30", headColor: "text-rose-400" },
  problem: { border: "border-amber-400/30", headColor: "text-amber-400" },
  focus: { border: "border-[var(--shell-accent)]/30", headColor: "text-[var(--shell-accent)]" },
};

export function PortalV4QuestionDiagnosis() {
  const { id } = useParams();
  const { data, isLoading } = useDiagnosis(id || "");
  const [filterCategory, setFilterCategory] = useState("전체");
  const [filterEngine, setFilterEngine] = useState("전체");
  const [expandedQuery, setExpandedQuery] = useState<number | null>(null);

  if (isLoading || !data) {
    return <div className="flex h-64 items-center justify-center text-[var(--shell-text-soft)]">로딩 중...</div>;
  }

  const notExposed = data.queries.filter((q) => q.gptRate === 0 && q.geminiRate === 0).length;
  const geminiExposed = data.queries.filter((q) => q.geminiRate > 0).length;
  const gptExposed = data.queries.filter((q) => q.gptRate > 0).length;

  const categories = ["전체", ...Array.from(new Set(data.queries.map((q) => q.category)))];

  const filteredQueries = data.queries.filter((q) => {
    if (filterCategory !== "전체" && q.category !== filterCategory) return false;
    if (filterEngine === "GPT 노출" && q.gptRate === 0) return false;
    if (filterEngine === "Gemini 노출" && q.geminiRate === 0) return false;
    return true;
  });

  return (
    <>
      {id && <HeaderV4DiagnosticButton boardId={id} title="V4 Diagnosis 진단" runner={runDiagnosisDiagnostics} />}
      <div className="mx-auto max-w-5xl space-y-6 p-6">
      {/* Topbar */}
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-accent)]">진단·원인 분석</div>
          <h1 className="mt-1 text-xl font-extrabold text-[var(--shell-text)]">쿼리별 AI 응답 진단</h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            핵심 질문별 노출 상태를 진단하고 AI 원문 답변에서 브랜드 언급 맥락을 확인합니다.
          </p>
        </div>
        <div className="flex flex-col items-end gap-1 text-right">
          <div className="text-xs text-[var(--shell-text-soft)]">측정 기간 2025.05.15 – 2025.06.26</div>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="flex flex-wrap gap-1.5">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setFilterCategory(cat)}
              className={`rounded-full px-3 py-1 text-[11px] font-semibold transition-colors ${
                filterCategory === cat
                  ? "bg-[var(--shell-accent)] text-[var(--shell-text)]"
                  : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)]"
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="ml-auto flex gap-1.5">
          {["전체", "GPT 노출", "Gemini 노출"].map((eng) => (
            <button
              key={eng}
              onClick={() => setFilterEngine(eng)}
              className={`rounded-full px-3 py-1 text-[11px] font-semibold transition-colors ${
                filterEngine === eng
                  ? "bg-[var(--shell-accent)] text-[var(--shell-text)]"
                  : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)]"
              }`}
            >
              {eng}
            </button>
          ))}
        </div>
      </div>

      {/* Query Summary */}
      <div className="flex flex-wrap gap-3 text-xs">
        <span className="rounded-lg border border-rose-400/40 bg-rose-500/10 px-3 py-1.5 font-bold text-rose-400 shell-badge-rose">미노출 {notExposed}개</span>
        <span className="rounded-lg border border-blue-400/40 bg-blue-500/10 px-3 py-1.5 font-bold text-blue-400 shell-badge-blue">Gemini 노출 {geminiExposed}개</span>
        <span className="rounded-lg border border-emerald-400/40 bg-emerald-500/10 px-3 py-1.5 font-bold text-emerald-400 shell-badge-emerald">GPT 노출 {gptExposed}개</span>
      </div>

      {/* Query Table */}
      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[700px] text-left text-xs">
            <thead>
              <tr className="border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]">
                <th className="px-4 py-3">#</th>
                <th className="px-4 py-3">쿼리</th>
                <th className="px-4 py-3">카테고리</th>
                <th className="px-4 py-3 text-right">GPT %</th>
                <th className="px-4 py-3 text-right">Gemini %</th>
                <th className="px-4 py-3 text-right">평균 순위</th>
                <th className="px-4 py-3 text-right"></th>
              </tr>
            </thead>
              {filteredQueries.map((q) => {
                const isExpanded = expandedQuery === q.queryIndex;
                const answers = data.rawAnswers.filter((a) => a.queryIndex === q.queryIndex);
                return (
                  <tbody key={q.queryIndex}>
                    <tr className="border-b border-[var(--shell-border)] hover:bg-[var(--shell-panel-soft)]">
                      <td className="px-4 py-2.5 text-[var(--shell-text-soft)]">Q{q.queryIndex + 1}</td>
                      <td className="max-w-[260px] truncate px-4 py-2.5 text-[var(--shell-text)]">{q.queryText}</td>
                      <td className="px-4 py-2.5">
                        <span className={`inline-block rounded-full px-2 py-0.5 text-[10px] font-bold ${categoryPillColor[q.category] || "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]"}`}>
                          {q.category}
                        </span>
                      </td>
                      <td className={`px-4 py-2.5 text-right font-semibold ${q.gptRate > 0 ? "text-emerald-400" : "text-[var(--shell-text-soft)]"}`}>
                        {q.gptRate.toFixed(1)}%
                      </td>
                      <td className={`px-4 py-2.5 text-right font-semibold ${q.geminiRate > 0 ? "text-blue-400" : "text-[var(--shell-text-soft)]"}`}>
                        {q.geminiRate.toFixed(1)}%
                      </td>
                      <td className="px-4 py-2.5 text-right text-[var(--shell-text-muted)]">
                        {q.rank ? q.rank.toFixed(1) : "-"}
                      </td>
                      <td className="px-4 py-2.5 text-right">
                        {answers.length > 0 && (
                          <button
                            onClick={() => setExpandedQuery(isExpanded ? null : q.queryIndex)}
                            className="rounded bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] font-bold text-[var(--shell-accent)] hover:bg-[var(--shell-panel-soft)]"
                          >
                            {isExpanded ? "접기" : "원문 보기"}
                          </button>
                        )}
                      </td>
                    </tr>
                    {isExpanded && answers.length > 0 && (
                      <tr>
                        <td colSpan={7} className="border-b border-[var(--shell-border)] bg-[var(--shell-panel-strong)] p-4">
                          <div className="space-y-3">
                            {answers.map((ans, ai) => (
                              <div key={ai} className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel)] p-3">
                                <div className="mb-1 flex items-center gap-2 text-[11px]">
                                  <span className="font-bold text-[var(--shell-text)]">
                                    {ans.engine === "gpt" ? "ChatGPT-4o" : "Gemini 1.5 Pro"}
                                  </span>
                                  {ans.brandMentioned && (
                                    <span className="rounded bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-bold text-emerald-400">언급됨</span>
                                  )}
                                  {!ans.brandMentioned && (
                                    <span className="rounded bg-rose-500/20 px-1.5 py-0.5 text-[10px] font-bold text-rose-400">미언급</span>
                                  )}
                                </div>
                                <p className="text-[11px] leading-relaxed text-[var(--shell-text-muted)]">
                                  {ans.answerStorageUrl
                                    ? <LazyStorageText storageUrl={ans.answerStorageUrl} />
                                    : ans.answerText}
                                </p>
                              </div>
                            ))}
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                );
              })}
          </table>
        </div>
      </article>

      {/* 노출 단계별 진단 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">노출 단계별 진단</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">현재 상태, 핵심 문제, 개선 방향을 요약합니다.</p>
      </div>

      <section className="grid gap-4 md:grid-cols-3">
        {data.diagnosticCards.map((card) => {
          const meta = diagCardMeta[card.type] || diagCardMeta.focus;
          return (
            <div key={card.type} className={`rounded-xl border ${meta.border} bg-[var(--shell-panel)] p-5`}>
              <h4 className="text-[11px] font-bold text-[var(--shell-text-soft)] uppercase tracking-wide mb-2">
                {card.type === "status" ? "현재 상태" : card.type === "problem" ? "핵심 문제" : "개선 방향"}
              </h4>
              <h3 className={`mb-2 text-sm font-bold ${meta.headColor}`}>{card.title}</h3>
              <p className="text-xs leading-relaxed text-[var(--shell-text-muted)]">{card.description}</p>
            </div>
          );
        })}
      </section>

      {/* 개선 우선순위 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">개선 우선순위</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">카테고리별 노출 공백 크기에 따른 우선순위입니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]">
                <th className="px-4 py-3">순위</th>
                <th className="px-4 py-3">개선 영역</th>
                <th className="px-4 py-3">진단</th>
                <th className="px-4 py-3">개선 방향</th>
              </tr>
            </thead>
            <tbody>
              {data.categoryGaps
                .sort((a, b) => b.gap - a.gap)
                .map((g, i) => (
                  <tr key={g.category} className={`border-b border-[var(--shell-border)] ${i === 0 ? "bg-rose-500/5" : ""}`}>
                    <td className="px-4 py-3">
                      <span className="rounded bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] font-bold text-[var(--shell-accent)]">{i + 1}순위</span>
                    </td>
                    <td className="px-4 py-3 font-medium text-[var(--shell-text)]">{g.categoryLabel}</td>
                    <td className="px-4 py-3 text-[var(--shell-text-muted)]">
                      {g.notExposedCount}/{g.totalCount}개 미노출 ({g.gap.toFixed(0)}%)
                    </td>
                    <td className="px-4 py-3 text-[var(--shell-text-muted)]">
                      {g.categoryLabel} 관련 콘텐츠 보강 필요
                    </td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
      </article>
    </div>
    </>
  );
}
