import { useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { fetchRecommendationsRaw, convertV3Recommendation, dismissV3Recommendation, snoozeV3Recommendation } from "./dataHub/api";
import type { RecommendationDoc } from "./dataHub/types";
import { num, quickWin, REC_CAT_LABEL } from "./utils";

function ImpactEffortMatrix({ recs }: { recs: RecommendationDoc[] }) {
  const size = 240, pad = 30, inner = size - pad * 2;
  return (
    <div className="flex justify-center mt-3">
      <svg viewBox={`0 0 ${size} ${size}`} className="w-full max-w-[300px]">
        <rect x={pad} y={pad} width={inner / 2} height={inner / 2} fill="rgba(95,211,154,.08)" />
        <rect x={pad + inner / 2} y={pad} width={inner / 2} height={inner / 2} fill="rgba(247,191,88,.08)" />
        <rect x={pad} y={pad + inner / 2} width={inner / 2} height={inner / 2} fill="rgba(148,163,184,.05)" />
        <rect x={pad + inner / 2} y={pad + inner / 2} width={inner / 2} height={inner / 2} fill="rgba(248,113,113,.08)" />
        <line x1={pad} y1={size - pad} x2={size - pad} y2={size - pad} stroke="#2a3850" />
        <line x1={pad} y1={pad} x2={pad} y2={size - pad} stroke="#2a3850" />
        <line x1={pad + inner / 2} y1={pad} x2={pad + inner / 2} y2={size - pad} stroke="#2a3850" strokeOpacity="0.5" strokeDasharray="2 2" />
        <line x1={pad} y1={pad + inner / 2} x2={size - pad} y2={pad + inner / 2} stroke="#2a3850" strokeOpacity="0.5" strokeDasharray="2 2" />
        <text x={pad + inner / 4} y={pad - 6} textAnchor="middle" fill="#5fd39a" fontSize="9" fontWeight="700">즉시 실행</text>
        <text x={pad + inner * 3 / 4} y={pad - 6} textAnchor="middle" fill="#f7bf58" fontSize="9" fontWeight="700">큰 작업</text>
        <text x={pad + inner / 4} y={size - pad + 14} textAnchor="middle" fill="#8ea0b8" fontSize="9">부가</text>
        <text x={pad + inner * 3 / 4} y={size - pad + 14} textAnchor="middle" fill="#f87171" fontSize="9">회피</text>
        <text x={12} y={pad + inner / 2} textAnchor="middle" fill="#8ea0b8" fontSize="9" transform={`rotate(-90,12,${pad + inner / 2})`}>Impact ↑</text>
        <text x={pad + inner / 2} y={size - 4} textAnchor="middle" fill="#8ea0b8" fontSize="9">Effort →</text>
        {recs.map((r, i) => {
          const x = pad + ((num(r.effortScore) - 1) / 4) * inner;
          const y = pad + (1 - (num(r.impactScore) - 1) / 4) * inner;
          const color = r.priority === "P1" ? "#f87171" : r.priority === "P2" ? "#f7bf58" : "#9ca3af";
          return <g key={i}><circle cx={x} cy={y} r="6" fill={color} fillOpacity={0.85} stroke="#0b111c" strokeWidth="1.5" /><title>{r.title}</title></g>;
        })}
      </svg>
    </div>
  );
}

function V4RecCard({ rec }: { rec: RecommendationDoc }) {
  const { id } = useParams();
  const qc = useQueryClient();
  const [sched, setSched] = useState(false);
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const invalidate = () => { qc.invalidateQueries({ queryKey: ["v3-recs", id] }); qc.invalidateQueries({ queryKey: ["v3-actions", id] }); };
  const convertM = useMutation({ mutationFn: () => convertV3Recommendation(id!, rec.id, { title: rec.title, description: rec.description, priority: rec.priority, category: rec.category, plannedStart: start || undefined, estimatedEnd: end || undefined, relatedQueries: rec.relatedQueries }), onSuccess: invalidate });
  const dismissM = useMutation({ mutationFn: () => dismissV3Recommendation(id!, rec.id), onSuccess: invalidate });
  const snoozeM = useMutation({ mutationFn: () => snoozeV3Recommendation(id!, rec.id, 7), onSuccess: invalidate });
  const busy = convertM.isPending || dismissM.isPending || snoozeM.isPending;

  const prioColor = rec.priority === "P1" ? "border-red-400/40" : rec.priority === "P2" ? "border-amber-400/40" : "border-[var(--shell-accent)]/40";
  const prioChip = rec.priority === "P1" ? "border border-rose-400/40 bg-rose-500/15 text-rose-400 shell-badge-rose" : rec.priority === "P2" ? "border border-amber-400/40 bg-amber-500/15 text-amber-400 shell-badge-amber" : "border border-sky-400/40 bg-sky-500/15 text-[var(--shell-accent)] shell-badge-sky";

  return (
    <div className={`rounded-lg border-l-[3px] ${prioColor} border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-4 space-y-2`}>
      <div className="flex flex-wrap gap-1.5">
        <span className={`rounded-full px-2 py-0.5 text-[10px] font-bold ${prioChip}`}>{rec.priority}</span>
        <span className="rounded-full bg-[var(--shell-panel-soft)] px-2 py-0.5 text-[10px] text-[var(--shell-text-muted)]">{REC_CAT_LABEL[rec.category || ""] || rec.category}</span>
        <span className="rounded-full border border-emerald-400/40 bg-emerald-500/15 px-2 py-0.5 text-[10px] text-emerald-400 shell-badge-emerald">Impact {rec.impactScore}/5</span>
        <span className="rounded-full border border-amber-400/40 bg-amber-500/15 px-2 py-0.5 text-[10px] text-amber-400 shell-badge-amber">Effort {rec.effortScore}/5</span>
        {num(rec.expectedDelta) > 0 && <span className="rounded-full border border-fuchsia-400/40 bg-fuchsia-500/15 px-2 py-0.5 text-[10px] text-fuchsia-400 shell-badge-fuchsia">예상 +{num(rec.expectedDelta).toFixed(1)}%p</span>}
      </div>
      <p className="text-xs font-bold text-[var(--shell-text)]">{rec.title}</p>
      {rec.description && <p className="text-[11px] text-[var(--shell-text-soft)] line-clamp-2">{rec.description}</p>}

      {convertM.isSuccess ? (
        <p className="text-[11px] text-emerald-400">작업 일정으로 전환됨</p>
      ) : dismissM.isSuccess ? (
        <p className="text-[11px] text-[var(--shell-text-soft)]">기각됨</p>
      ) : snoozeM.isSuccess ? (
        <p className="text-[11px] text-[var(--shell-text-soft)]">7일 미룸</p>
      ) : (
        <>
          <div className="flex flex-wrap gap-2 pt-1">
            <button type="button" onClick={() => setSched((s) => !s)} disabled={busy} className="rounded-full bg-[var(--shell-accent-soft)] px-2.5 py-1 text-[10px] font-bold text-[var(--shell-accent)] hover:bg-[var(--shell-accent-soft)] transition-colors disabled:opacity-50">일정 추가 / 작업 전환</button>
            <button type="button" onClick={() => snoozeM.mutate()} disabled={busy} className="rounded-full bg-[var(--shell-panel-soft)] px-2.5 py-1 text-[10px] text-[var(--shell-text-muted)] hover:bg-[var(--shell-panel-soft)] transition-colors disabled:opacity-50">미루기 (7일)</button>
            <button type="button" onClick={() => { if (confirm("이 추천을 기각할까요?")) dismissM.mutate(); }} disabled={busy} className="rounded-full bg-[var(--shell-panel-soft)] px-2.5 py-1 text-[10px] text-rose-400 hover:bg-rose-500/10 transition-colors disabled:opacity-50">기각</button>
          </div>
          {sched && (
            <div className="flex flex-wrap gap-3 items-end pt-2">
              <label className="text-[11px] text-[var(--shell-text-soft)]">시작일<br /><input type="date" value={start} onChange={(e) => setStart(e.target.value)} className="mt-0.5 rounded-md border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2 py-1 text-xs text-[var(--shell-text)]" /></label>
              <label className="text-[11px] text-[var(--shell-text-soft)]">완료 예정일<br /><input type="date" value={end} onChange={(e) => setEnd(e.target.value)} className="mt-0.5 rounded-md border border-[var(--shell-border)] bg-[var(--shell-panel)] px-2 py-1 text-xs text-[var(--shell-text)]" /></label>
              <button type="button" onClick={() => convertM.mutate()} disabled={busy} className="rounded-full bg-emerald-500/20 px-3 py-1.5 text-[10px] font-bold text-emerald-400 hover:bg-emerald-500/30 transition-colors disabled:opacity-50">{convertM.isPending ? "전환 중..." : "작업 일정으로 전환"}</button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

export function V4TrackRecommendations() {
  const { id } = useParams();
  const recsQ = useQuery({ queryKey: ["v3-recs", id], queryFn: () => fetchRecommendationsRaw(id!), enabled: !!id });
  const pending: RecommendationDoc[] = recsQ.data?.groups?.pending || recsQ.data?.recommendations || [];
  const sorted = [...pending].sort((a, b) => quickWin(b) - quickWin(a));

  return (
    <section className="space-y-4">
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">AI 검색결과 개선 방향 — 검토할 추천</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">측정 결과 기반 추천 과제. 효과(예상 +%p) 크고 작업량 적은 순.</p>
      </div>

      {pending.length > 0 && (
        <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
          <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
            <span className="text-xs font-medium text-[var(--shell-text)]">어떤 과제부터 하면 효율적인가요?</span>
            <span className="text-[11px] text-[var(--shell-text-soft)]">Pending {pending.length}</span>
          </div>
          <div className="p-5">
            <p className="text-[11px] text-[var(--shell-text-soft)]">우측 상단 = 효과 크고 쉬움(즉시 실행 추천) / 색 = 우선순위(P1 빨강, P2 주황, P3 회색)</p>
            <ImpactEffortMatrix recs={pending} />
          </div>
        </article>
      )}

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">검토하고, 일정을 잡아 작업으로 전환하세요</span>
          <span className="text-[11px] text-[var(--shell-text-soft)]">{pending.length}건</span>
        </div>
        <div className="space-y-3 p-5">
          {sorted.map((r, i) => <V4RecCard key={r.id || i} rec={r} />)}
          {pending.length === 0 && <p className="text-xs text-[var(--shell-text-soft)]">검토할 추천이 아직 없습니다. (측정/분석 후 자동 생성)</p>}
        </div>
      </article>
    </section>
  );
}
