import { Lightbulb, ClipboardList, GitBranch, Palette, Rocket, ListTodo, CheckCircle2 } from "lucide-react";
import { TabLayout, useActiveTab, type TabDef } from "../../components/shared/TabLayout";
import { Recommended } from "./actions/Recommended";
import { ActionPlan } from "./actions/ActionPlan";
import { ContentStudio, Pipeline } from "./actions/ContentStudio";
import { DeployQueue, WorkQueue, Completed } from "./actions/DeployComplete";

export const ACTIONS_TABS: TabDef[] = [
  { label: "Recommended", slug: "recommended", icon: Lightbulb },
  { label: "Action Plan", slug: "plan", icon: ClipboardList },
  { label: "Pipeline", slug: "pipeline", icon: GitBranch },
  { label: "Content Studio", slug: "studio", icon: Palette },
  { label: "Deploy Queue", slug: "deploy", icon: Rocket },
  { label: "Work Queue", slug: "queue", icon: ListTodo },
  { label: "Completed", slug: "completed", icon: CheckCircle2 },
];

export function ActionsV2() {
  const activeTab = useActiveTab(ACTIONS_TABS, "workspace/actions");

  return (
    <TabLayout
      title="Actions"
      description="개선 액션을 계획하고 만들고 배포하고 추적합니다"
      tabs={ACTIONS_TABS}
      basePath="workspace/actions"
    >
      {activeTab === "recommended" && <Recommended />}
      {activeTab === "plan" && <ActionPlan />}
      {activeTab === "pipeline" && <Pipeline />}
      {activeTab === "studio" && <ContentStudio />}
      {activeTab === "deploy" && <DeployQueue />}
      {activeTab === "queue" && <WorkQueue />}
      {activeTab === "completed" && <Completed />}
    </TabLayout>
  );
}
