import { useCallback, useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { Bot, Cpu, Link2, Users, Wrench, Database, ChevronDown, ChevronRight, Copy, Download, Check, Loader2 } from "lucide-react";
import {
  getBoard,
  listSnsConnections,
  updateBoard,
} from "../../db/boards";
import { useCommand } from "../../hooks/useCommand";
import { useRunSteps } from "../../hooks/useRunSteps";
import { extractBoardData, type ExportSection } from "../../db/portalV3";
import type { Board, CommandType, SnsConnection, StepStatus } from "../../db/collections";
import { TabLayout, useActiveTab, type TabDef } from "../../components/shared/TabLayout";
import { EmptyState } from "../../components/shared/EmptyState";

const isDev = import.meta.env.DEV;

export const SETTINGS_TABS: TabDef[] = [
  { label: "Project", slug: "project", icon: Wrench },
  { label: "Integrations", slug: "integrations", icon: Link2 },
  { label: "Automation", slug: "automation", icon: Bot },
  { label: "Runtime & Models", slug: "runtime", icon: Cpu },
  { label: "Team / Access", slug: "team", icon: Users },
  ...(isDev ? [{ label: "Data Export", slug: "data-export", icon: Database } as TabDef] : []),
];

export function SettingsV2() {
  const activeTab = useActiveTab(SETTINGS_TABS, "workspace/settings");
  const { id } = useParams<{ id: string }>();
  const cmd = useCommand(id);

  const [board, setBoard] = useState<Board | null>(null);
  const [snsConns, setSnsConns] = useState<SnsConnection[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const [b, conns] = await Promise.all([
      getBoard(id).catch(() => null),
      listSnsConnections(id).catch(() => []),
    ]);
    setBoard(b);
    setSnsConns(conns);
    setLoading(false);
  }, [id]);

  useEffect(() => { load(); }, [load]);

  return (
    <TabLayout
      title="Settings"
      description="연동, 자동화, 프로젝트 설정, 팀 권한을 관리합니다"
      tabs={SETTINGS_TABS}
      basePath="workspace/settings"
    >
      {loading ? (
        <Loading />
      ) : (
        <>
          {activeTab === "integrations" && <IntegrationsTab board={board} snsConns={snsConns} />}
          {activeTab === "automation" && <AutomationTab board={board} cmd={cmd} onRefresh={load} />}
          {activeTab === "project" && <ProjectTab board={board} boardId={id!} cmd={cmd} onRefresh={load} />}
          {activeTab === "runtime" && <RuntimeTab />}
          {activeTab === "team" && <TeamTab />}
          {activeTab === "data-export" && <DataExportTab boardId={id!} />}
        </>
      )}
    </TabLayout>
  );
}

