interface AutomationCard {
  title: string;
  description: string;
  command: CommandType;
  cycle: string;
  relatedStep?: string;
}

const AUTOMATIONS: AutomationCard[] = [
  { title: "AI Simulation", description: "Automatically measure brand visibility across AI engines (ChatGPT, Gemini, Claude, etc.)", command: "run_geo_probe", cycle: "Daily", relatedStep: "geoProbe" },
  { title: "Full Analysis", description: "Run SEO/GEO analysis pipeline and update action plans", command: "onboard", cycle: "Weekly", relatedStep: "crawl" },
  { title: "Content Generation", description: "Auto-generate SNS content drafts based on analysis results", command: "generate_sns_drafts", cycle: "Weekly", relatedStep: "content" },
  { title: "Trend Snapshot", description: "Capture current mention rate, exposure rate, and key metrics", command: "create_trend_snapshot", cycle: "Daily" },
];

function stepStatusStyle(status?: StepStatus): { text: string; cls: string } {
  switch (status) {
    case "complete": return { text: "Complete", cls: "bg-emerald-500/10 text-emerald-600" };
    case "running": return { text: "Running", cls: "bg-blue-500/10 text-blue-600" };
    case "pending": return { text: "Pending", cls: "bg-amber-500/10 text-amber-500" };
    case "failed": return { text: "Failed", cls: "bg-rose-500/10 text-rose-500" };
    default: return { text: "Idle", cls: "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)]" };
  }
}

function AutomationTab({ board, cmd, onRefresh }: { board: Board | null; cmd: ReturnType<typeof useCommand>; onRefresh: () => void }) {
  const [runningCmd, setRunningCmd] = useState<CommandType | null>(null);
  const { steps: stepStatus } = useRunSteps(board?.id);

  const handleRun = async (command: CommandType) => {
    setRunningCmd(command);
    await cmd.execute(command);
    setRunningCmd(null);
    onRefresh();
  };

  return (
    <div className="space-y-6">
      {/* Running indicator */}
      {cmd.isRunning && (
        <div className="rounded-2xl border border-[var(--shell-accent)]/30 bg-[var(--shell-accent)]/5 px-5 py-4">
          <div className="flex items-center gap-2 text-sm font-medium text-[var(--shell-accent)]">
            <span className="inline-flex h-2 w-2 animate-pulse rounded-full bg-[var(--shell-accent)]" />
            {cmd.message || "Running..."}
          </div>
          {cmd.progress > 0 && (
            <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[var(--shell-border)]">
              <div className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500" style={{ width: `${Math.min(cmd.progress, 100)}%` }} />
            </div>
          )}
        </div>
      )}

      {/* Automation cards */}
      <div className="grid gap-4 md:grid-cols-2">
        {AUTOMATIONS.map((auto) => {
          const status = stepStatusStyle(auto.relatedStep ? stepStatus[auto.relatedStep as keyof typeof stepStatus] : undefined);
          const isThis = cmd.isRunning && runningCmd === auto.command;
          return (
            <div key={auto.command} className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
              <div className="flex items-center gap-2">
                <h4 className="text-sm font-semibold text-[var(--shell-text)]">{auto.title}</h4>
                <span className={`rounded-md px-2 py-0.5 text-[10px] font-medium ${status.cls}`}>{status.text}</span>
              </div>
              <p className="mt-1.5 text-xs leading-relaxed text-[var(--shell-text-muted)]">{auto.description}</p>
              <div className="mt-4 flex items-center justify-between">
                <span className="rounded-md bg-[var(--shell-panel-soft)] px-2 py-1 text-[10px] text-[var(--shell-text-muted)]">Cycle: {auto.cycle}</span>
                <button
                  type="button"
                  onClick={() => handleRun(auto.command)}
                  disabled={cmd.isRunning}
                  className="rounded-xl border border-[var(--shell-border)] px-3 py-2 text-xs font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
                >
                  {isThis ? "Running..." : "Run Now"}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Project ────────────────────────────────────────────────

function ProjectTab({ board, boardId, cmd, onRefresh }: { board: Board | null; boardId: string; cmd: ReturnType<typeof useCommand>; onRefresh: () => void }) {
  const [siteName, setSiteName] = useState(board?.siteName ?? "");
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    setSaving(true);
    await updateBoard(boardId, { siteName });
    setSaving(false);
  };

  const handleReanalyze = async () => {
    await cmd.execute("onboard");
    onRefresh();
  };

  if (!board) {
    return <EmptyState icon={Wrench} title="Board not found" description="프로젝트 정보를 불러올 수 없습니다" />;
  }

  return (
    <div className="space-y-6">
      {/* Board info */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">Project Information</h3>
        <div className="mt-3 space-y-2">
          <div
            className="flex cursor-pointer items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3 transition hover:border-[var(--shell-accent)]/40"
            title="Click to copy Board ID"
            onClick={() => void navigator.clipboard.writeText(boardId)}
          >
            <span className="text-sm text-[var(--shell-text-muted)]">Board ID</span>
            <span className="font-mono text-xs text-[var(--shell-text-soft)]">{boardId}</span>
          </div>
          <InfoRow label="URL" value={board.url} />
          <InfoRow label="Domain" value={board.domain} />
          <InfoRow
            label="Status"
            value={
              board.status === "complete"
                ? "완료"
                : board.status === "failed"
                  ? "실패"
                  : board.status === "processing"
                    ? "작업 중"
                    : "대기 중"
            }
          />
          <InfoRow label="Created" value={board.createdAt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })} />
          {board.completedAt && <InfoRow label="Completed" value={board.completedAt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" })} />}
        </div>
      </div>

      {/* Site name edit */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">Site Name</h3>
        <div className="mt-3 flex items-end gap-3">
          <label className="block flex-1">
            <span className="mb-1 block text-[10px] uppercase tracking-wider text-[var(--shell-text-muted)]">Display Name</span>
            <input value={siteName} onChange={(e) => setSiteName(e.target.value)} className="shell-input w-full rounded-xl px-3 py-2.5 text-sm" />
          </label>
          <button type="button" onClick={handleSave} disabled={saving} className="rounded-xl border border-[var(--shell-border)] px-4 py-2.5 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50">
            {saving ? "Saving..." : "Save"}
          </button>
        </div>
      </div>

      {/* Re-analyze */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">Re-analyze</h3>
        <p className="mt-1 text-xs text-[var(--shell-text-muted)]">Run the full onboarding analysis pipeline from scratch</p>
        <div className="mt-3">
          <button type="button" onClick={handleReanalyze} disabled={cmd.isRunning} className="rounded-xl border border-[var(--shell-border)] px-4 py-2.5 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50">
            {cmd.isRunning ? "Running..." : "Run Full Analysis"}
          </button>
        </div>
        {cmd.isRunning && cmd.progress > 0 && (
          <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[var(--shell-border)]">
            <div className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-500" style={{ width: `${Math.min(cmd.progress, 100)}%` }} />
          </div>
        )}
        {cmd.isComplete && <p className="mt-2 text-xs text-emerald-600">Analysis complete</p>}
        {cmd.isFailed && cmd.error && <p className="mt-2 text-xs text-rose-500">{cmd.error}</p>}
      </div>
    </div>
  );
}

