// ── Data Export ───────────────────────────────────────────

function DataExportTab({ boardId }: { boardId: string }) {
  const [sections, setSections] = useState<ExportSection[]>([]);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0, label: "" });
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  const handleExtract = async () => {
    setLoading(true);
    setSections([]);
    setExpanded(new Set());
    try {
      const result = await extractBoardData(boardId, (done, total, label) => {
        setProgress({ done, total, label });
      });
      setSections(result);
    } finally {
      setLoading(false);
    }
  };

  const toggle = (key: string) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const toTsExport = (section: ExportSection): string => {
    const varName = `mock${section.key.charAt(0).toUpperCase()}${section.key.slice(1)}`;
    const json = JSON.stringify(section.data, null, 2);
    return `export const ${varName} = ${json};\n`;
  };

  const copySection = (section: ExportSection) => {
    navigator.clipboard.writeText(toTsExport(section)).then(() => {
      setCopiedKey(section.key);
      setTimeout(() => setCopiedKey(null), 2000);
    });
  };

  const downloadAll = () => {
    const parts = sections.map((s) => {
      const header = `// ── ${s.label} (${s.path}) ── ${s.type === "collection" ? `${s.docCount} docs` : "single doc"}\n`;
      return header + toTsExport(s);
    });
    const content = `/**\n * Board Data Export\n * Board ID: ${boardId}\n * Exported: ${new Date().toISOString()}\n * Sections: ${sections.length}\n */\n\n${parts.join("\n")}`;
    const blob = new Blob([content], { type: "text/typescript" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `board-export-${boardId.slice(0, 8)}-${new Date().toISOString().slice(0, 10)}.ts`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const totalDocs = sections.reduce((acc, s) => acc + s.docCount, 0);

  return (
    <div className="space-y-6">
      {/* Header card */}
      <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
        <h3 className="text-sm font-semibold text-[var(--shell-text)]">Firestore Data Export</h3>
        <p className="mt-1 text-xs leading-relaxed text-[var(--shell-text-muted)]">
          이 보드의 모든 Firestore subcollection 데이터를 mockData 형태의 TypeScript로 추출합니다.
          추출된 데이터는 <code className="rounded bg-[var(--shell-panel-soft)] px-1 py-0.5 text-[10px]">src/pages/portalV3/mockData/</code> 파일과 동일한 구조입니다.
        </p>
        <div className="mt-4 flex items-center gap-3">
          <button
            type="button"
            onClick={handleExtract}
            disabled={loading}
            className="rounded-xl border border-[var(--shell-border)] px-4 py-2.5 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-[var(--shell-accent)] hover:text-[var(--shell-accent)] disabled:opacity-50"
          >
            {loading ? (
              <span className="flex items-center gap-2">
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Extracting...
              </span>
            ) : (
              <span className="flex items-center gap-2">
                <Database className="h-3.5 w-3.5" />
                Extract All Data
              </span>
            )}
          </button>
          {sections.length > 0 && (
            <button
              type="button"
              onClick={downloadAll}
              className="rounded-xl border border-[var(--shell-border)] px-4 py-2.5 text-sm font-medium text-[var(--shell-text)] transition-colors hover:border-emerald-500 hover:text-emerald-500"
            >
              <span className="flex items-center gap-2">
                <Download className="h-3.5 w-3.5" />
                Download .ts
              </span>
            </button>
          )}
        </div>

        {/* Progress */}
        {loading && progress.total > 0 && (
          <div className="mt-4">
            <div className="flex items-center justify-between text-[10px] text-[var(--shell-text-muted)]">
              <span>{progress.label}</span>
              <span>{progress.done}/{progress.total}</span>
            </div>
            <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-[var(--shell-border)]">
              <div
                className="h-full rounded-full bg-[var(--shell-accent)] transition-all duration-300"
                style={{ width: `${Math.round((progress.done / progress.total) * 100)}%` }}
              />
            </div>
          </div>
        )}
      </div>

      {/* Results summary */}
      {sections.length > 0 && (
        <div className="rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-5">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-semibold text-[var(--shell-text)]">
              Extracted Data
            </h3>
            <div className="flex items-center gap-3 text-[10px] text-[var(--shell-text-muted)]">
              <span>{sections.length} sections</span>
              <span>{totalDocs} documents</span>
            </div>
          </div>

          <div className="mt-4 space-y-1">
            {sections.map((s) => {
              const isOpen = expanded.has(s.key);
              const json = JSON.stringify(s.data, null, 2);
              const lines = json.split("\n").length;
              const isCopied = copiedKey === s.key;

              return (
                <div key={s.key} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)]">
                  {/* Row header */}
                  <button
                    type="button"
                    onClick={() => toggle(s.key)}
                    className="flex w-full items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-[var(--shell-border)]/30"
                  >
                    {isOpen
                      ? <ChevronDown className="h-3.5 w-3.5 shrink-0 text-[var(--shell-text-muted)]" />
                      : <ChevronRight className="h-3.5 w-3.5 shrink-0 text-[var(--shell-text-muted)]" />
                    }
                    <div className="min-w-0 flex-1">
                      <span className="text-sm font-medium text-[var(--shell-text)]">{s.label}</span>
                      <span className="ml-2 text-[10px] text-[var(--shell-text-muted)]">{s.path}</span>
                    </div>
                    <div className="flex shrink-0 items-center gap-2">
                      <span className={`rounded-md px-1.5 py-0.5 text-[9px] font-medium ${
                        s.type === "collection"
                          ? "bg-blue-500/10 text-blue-400"
                          : "bg-emerald-500/10 text-emerald-400"
                      }`}>
                        {s.type === "collection" ? `${s.docCount} docs` : "doc"}
                      </span>
                      <span className="text-[10px] text-[var(--shell-text-muted)]">{lines} lines</span>
                    </div>
                  </button>

                  {/* Expanded content */}
                  {isOpen && (
                    <div className="border-t border-[var(--shell-border)]">
                      <div className="flex items-center justify-end gap-1 px-3 py-1.5">
                        <button
                          type="button"
                          onClick={(e) => { e.stopPropagation(); copySection(s); }}
                          className="flex items-center gap-1 rounded-md px-2 py-1 text-[10px] text-[var(--shell-text-muted)] transition-colors hover:bg-[var(--shell-border)]/40 hover:text-[var(--shell-text)]"
                        >
                          {isCopied ? <Check className="h-3 w-3 text-emerald-400" /> : <Copy className="h-3 w-3" />}
                          {isCopied ? "Copied!" : "Copy as TS"}
                        </button>
                      </div>
                      <pre className="max-h-[400px] overflow-auto px-4 pb-4 text-[11px] leading-relaxed text-[var(--shell-text-soft)]">
                        <code>{json}</code>
                      </pre>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Empty state */}
      {!loading && sections.length === 0 && (
        <EmptyState
          icon={Database}
          title="No data extracted yet"
          description="Extract All Data 버튼을 눌러 이 보드의 Firestore 데이터를 추출하세요"
        />
      )}
    </div>
  );
}

// ── Shared ─────────────────────────────────────────────────

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
      <span className="text-sm text-[var(--shell-text-muted)]">{label}</span>
      <span className="text-right text-sm font-medium text-[var(--shell-text)]">{value}</span>
    </div>
  );
}

function Loading() {
  return <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">Loading...</div>;
}
