import { useState, useRef, useCallback, useEffect } from "react";
import { ArrowLeft, Database, Play, Square, CheckCircle2, AlertCircle, Loader2, ChevronDown, SkipForward } from "lucide-react";
import { Link } from "react-router-dom";
import { createNeonClient } from "./neonClient";
import { runMigration } from "./migrationEngine";
import { fetchOnboardings } from "./pgFetchers";
import { MIGRATION_PHASES } from "./types";
import type { MigrationLog, OnboardingRow } from "./types";

type RunMode = "single" | "from_here";

const __DEV__ = import.meta.env.DEV;

export function MigrationPage() {
  if (!__DEV__) {
    return (
      <div className="flex h-screen items-center justify-center">
        <p className="text-gray-500">This page is only available in development mode.</p>
      </div>
    );
  }

  return <MigrationContent />;
}

function MigrationContent() {
  const [databaseUrl, setDatabaseUrl] = useState(() => localStorage.getItem("__migration_db_url") || "");
  const [status, setStatus] = useState<"idle" | "connecting" | "ready" | "running" | "complete" | "error">("idle");
  const [onboardings, setOnboardings] = useState<OnboardingRow[]>([]);
  const [selectedOnboarding, setSelectedOnboarding] = useState<string>("");
  const [runMode, setRunMode] = useState<RunMode>("single");
  const [targetBoardId, setTargetBoardId] = useState("");
  const [useSameId, setUseSameId] = useState(true);
  const [logs, setLogs] = useState<MigrationLog[]>([]);
  const [currentPhase, setCurrentPhase] = useState<string | null>(null);
  const [currentTable, setCurrentTable] = useState<string | null>(null);
  const [currentBoard, setCurrentBoard] = useState<string | null>(null);
  const [totalDocs, setTotalDocs] = useState(0);
  const [errorMsg, setErrorMsg] = useState("");
  const abortRef = useRef<AbortController | null>(null);
  const logContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (logContainerRef.current) {
      logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [logs]);

  const addLog = useCallback((log: MigrationLog) => {
    setLogs((prev) => [...prev, log]);
  }, []);

  const handleConnect = async () => {
    if (!databaseUrl.trim()) return;
    setStatus("connecting");
    setErrorMsg("");
    localStorage.setItem("__migration_db_url", databaseUrl);

    try {
      const sql = createNeonClient(databaseUrl);
      const rows = await fetchOnboardings(sql);
      setOnboardings(rows as unknown as OnboardingRow[]);
      setStatus("ready");
      addLog({ timestamp: new Date().toISOString(), level: "success", message: `Connected! Found ${rows.length} onboarding(s).` });
    } catch (err) {
      setStatus("error");
      setErrorMsg(err instanceof Error ? err.message : "Connection failed");
      addLog({ timestamp: new Date().toISOString(), level: "error", message: `Connection failed: ${err}` });
    }
  };

  const handleStartMigration = async () => {
    if (!selectedOnboarding) return;

    const isAll = selectedOnboarding === "__ALL__";
    const isFromHere = !isAll && runMode === "from_here";

    if (!isAll && !isFromHere) {
      const boardId = useSameId ? selectedOnboarding : targetBoardId.trim();
      if (!boardId) return;
    }

    setStatus("running");
    setLogs([]);
    setTotalDocs(0);
    setErrorMsg("");
    abortRef.current = new AbortController();

    try {
      const sql = createNeonClient(databaseUrl);

      if (isAll || isFromHere) {
        const startIdx = isFromHere
          ? onboardings.findIndex((ob) => ob.id === selectedOnboarding)
          : 0;
        const subset = onboardings.slice(startIdx);
        const totalCount = subset.length;

        if (isFromHere) {
          addLog({ timestamp: new Date().toISOString(), level: "info", message: `Starting from board ${startIdx + 1}/${onboardings.length}, migrating ${totalCount} remaining boards` });
        }

        let grandTotal = 0;
        for (let i = 0; i < subset.length; i++) {
          if (abortRef.current.signal.aborted) throw new Error("Migration aborted by user");
          const ob = subset[i];
          const globalIdx = startIdx + i;
          const boardLabel = `[${globalIdx + 1}/${onboardings.length}] ${ob.site_name || ob.domain}`;
          setCurrentBoard(boardLabel);
          addLog({ timestamp: new Date().toISOString(), level: "info", message: `--- ${boardLabel} (${ob.id.slice(0, 8)}...) ---` });
          const count = await runMigration(
            sql,
            ob.id,
            ob.id,
            addLog,
            (update) => {
              if (update.currentPhase) setCurrentPhase(update.currentPhase);
              if (update.currentTable) setCurrentTable(update.currentTable);
            },
            abortRef.current.signal,
          );
          grandTotal += count;
          setTotalDocs(grandTotal);
        }
        setStatus("complete");
      } else {
        const boardId = useSameId ? selectedOnboarding : targetBoardId.trim();
        const ob = onboardings.find((o) => o.id === selectedOnboarding);
        setCurrentBoard(ob ? (ob.site_name || ob.domain) : boardId.slice(0, 8));
        const count = await runMigration(
          sql,
          boardId,
          selectedOnboarding,
          addLog,
          (update) => {
            if (update.currentPhase) setCurrentPhase(update.currentPhase);
            if (update.currentTable) setCurrentTable(update.currentTable);
          },
          abortRef.current.signal,
        );
        setTotalDocs(count);
        setStatus("complete");
      }
    } catch (err) {
      if ((err as Error).message === "Migration aborted by user") {
        addLog({ timestamp: new Date().toISOString(), level: "warn", message: "Migration aborted by user" });
        setStatus("ready");
      } else {
        setErrorMsg(err instanceof Error ? err.message : "Migration failed");
        addLog({ timestamp: new Date().toISOString(), level: "error", message: `Migration failed: ${err}` });
        setStatus("error");
      }
    }
  };

  const handleAbort = () => {
    abortRef.current?.abort();
  };

  const effectiveBoardId = useSameId ? selectedOnboarding : targetBoardId;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="mx-auto max-w-4xl space-y-6">
        {/* Back link */}
        <Link to="/" className="inline-flex items-center gap-1.5 text-sm text-gray-500 hover:text-gray-800 transition">
          <ArrowLeft className="h-4 w-4" />
          <span>Landing</span>
        </Link>

        {/* Header */}
        <div className="flex items-center gap-3">
          <Database className="h-7 w-7 text-blue-600" />
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Data Migration</h1>
            <p className="text-sm text-gray-500">PostgreSQL (Neon) to Firestore</p>
          </div>
        </div>

        {/* Connection Panel */}
        <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm">
          <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-gray-600">Database Connection</h2>
          <div className="flex gap-3">
            <input
              type="password"
              value={databaseUrl}
              onChange={(e) => setDatabaseUrl(e.target.value)}
              placeholder="postgresql://user:pass@host/dbname?sslmode=require"
              className="flex-1 rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-mono focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              disabled={status === "running"}
            />
            <button
              onClick={handleConnect}
              disabled={!databaseUrl.trim() || status === "running" || status === "connecting"}
              className="shrink-0 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-medium text-white transition hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed"
            >
              {status === "connecting" ? (
                <span className="flex items-center gap-2"><Loader2 className="h-4 w-4 animate-spin" /> Connecting...</span>
              ) : "Connect"}
            </button>
          </div>
          {status === "error" && errorMsg && (
            <p className="mt-2 flex items-center gap-1.5 text-sm text-red-600">
              <AlertCircle className="h-4 w-4" /> {errorMsg}
            </p>
          )}
        </div>

        {/* Onboarding Selection */}
        {(status === "ready" || status === "running" || status === "complete") && (
          <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm">
            <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-gray-600">Migration Target</h2>
            <div className="space-y-4">
              <div>
                <label className="mb-1.5 block text-sm font-medium text-gray-700">Source Onboarding (PG)</label>
                <div className="relative">
                  <select
                    value={selectedOnboarding}
                    onChange={(e) => {
                      setSelectedOnboarding(e.target.value);
                      if (useSameId) setTargetBoardId(e.target.value);
                    }}
                    disabled={status === "running"}
                    className="w-full appearance-none rounded-lg border border-gray-300 bg-white px-4 py-2.5 pr-10 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  >
                    <option value="">Select an onboarding...</option>
                    <option value="__ALL__">-- All Onboardings ({onboardings.length}) --</option>
                    {onboardings.map((ob) => (
                      <option key={ob.id} value={ob.id}>
                        {ob.site_name || ob.domain} ({ob.status}) - {ob.id.slice(0, 8)}...
                      </option>
                    ))}
                  </select>
                  <ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
                </div>
              </div>

              {selectedOnboarding === "__ALL__" && (
                <p className="text-xs text-amber-600 font-medium">
                  All {onboardings.length} onboardings will be migrated using their original PG IDs as Firestore board IDs.
                </p>
              )}

              {selectedOnboarding && selectedOnboarding !== "__ALL__" && (
              <div className="space-y-3">
                {/* Run mode selector */}
                <div className="flex gap-3">
                  <label className="flex items-center gap-2 text-sm font-medium text-gray-700 cursor-pointer">
                    <input
                      type="radio"
                      name="runMode"
                      value="single"
                      checked={runMode === "single"}
                      onChange={() => setRunMode("single")}
                      disabled={status === "running"}
                      className="h-4 w-4 border-gray-300 text-blue-600"
                    />
                    Single board only
                  </label>
                  <label className="flex items-center gap-2 text-sm font-medium text-gray-700 cursor-pointer">
                    <input
                      type="radio"
                      name="runMode"
                      value="from_here"
                      checked={runMode === "from_here"}
                      onChange={() => setRunMode("from_here")}
                      disabled={status === "running"}
                      className="h-4 w-4 border-gray-300 text-blue-600"
                    />
                    <span className="flex items-center gap-1">
                      <SkipForward className="h-3.5 w-3.5" />
                      From here to end
                    </span>
                  </label>
                </div>

                {runMode === "from_here" && (
                  <p className="text-xs text-amber-600 font-medium">
                    Will migrate from this board through the end of the list ({onboardings.length - onboardings.findIndex((o) => o.id === selectedOnboarding)} boards remaining).
                  </p>
                )}

                {runMode === "single" && (
                <div>
                  <label className="flex items-center gap-2 text-sm font-medium text-gray-700">
                    <input
                      type="checkbox"
                      checked={useSameId}
                      onChange={(e) => setUseSameId(e.target.checked)}
                      disabled={status === "running"}
                      className="h-4 w-4 rounded border-gray-300 text-blue-600"
                    />
                    Use same ID for Firestore board
                  </label>
                  {!useSameId && (
                    <input
                      type="text"
                      value={targetBoardId}
                      onChange={(e) => setTargetBoardId(e.target.value)}
                      placeholder="Custom Firestore board ID"
                      disabled={status === "running"}
                      className="mt-2 w-full rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-mono focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                    />
                  )}
                </div>
                )}
              </div>
              )}

              {effectiveBoardId && selectedOnboarding !== "__ALL__" && runMode === "single" && (
                <p className="text-xs text-gray-500">
                  Target path: <code className="rounded bg-gray-100 px-1.5 py-0.5">boards/{effectiveBoardId}</code>
                </p>
              )}

              <div className="flex gap-3">
                <button
                  onClick={handleStartMigration}
                  disabled={!selectedOnboarding || (selectedOnboarding !== "__ALL__" && runMode === "single" && !effectiveBoardId) || status === "running"}
                  className="flex items-center gap-2 rounded-lg bg-green-600 px-5 py-2.5 text-sm font-medium text-white transition hover:bg-green-700 disabled:bg-gray-300 disabled:cursor-not-allowed"
                >
                  {runMode === "from_here" && selectedOnboarding !== "__ALL__" ? (
                    <><SkipForward className="h-4 w-4" /> Resume from here</>
                  ) : (
                    <><Play className="h-4 w-4" /> Start Migration</>
                  )}
                </button>
                {status === "running" && (
                  <button
                    onClick={handleAbort}
                    className="flex items-center gap-2 rounded-lg bg-red-600 px-5 py-2.5 text-sm font-medium text-white transition hover:bg-red-700"
                  >
                    <Square className="h-4 w-4" /> Abort
                  </button>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Progress Panel */}
        {(status === "running" || status === "complete") && (
          <div className="rounded-xl border border-gray-200 bg-white p-5 shadow-sm">
            <div className="mb-3 flex items-center justify-between">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-gray-600">Progress</h2>
              {status === "running" && (
                <span className="flex items-center gap-1.5 text-sm text-blue-600">
                  <Loader2 className="h-4 w-4 animate-spin" /> Running...
                </span>
              )}
              {status === "complete" && (
                <span className="flex items-center gap-1.5 text-sm text-green-600">
                  <CheckCircle2 className="h-4 w-4" /> Complete
                </span>
              )}
            </div>

            {/* Phase indicators */}
            <div className="mb-4 grid grid-cols-4 gap-2">
              {MIGRATION_PHASES.map((phase) => {
                const isCurrent = currentPhase === phase.id;
                const phaseIdx = MIGRATION_PHASES.findIndex((p) => p.id === phase.id);
                const currentIdx = MIGRATION_PHASES.findIndex((p) => p.id === currentPhase);
                const isComplete = currentIdx > phaseIdx || status === "complete";
                return (
                  <div
                    key={phase.id}
                    className={`rounded-lg border px-3 py-2 text-xs font-medium transition ${
                      isComplete
                        ? "border-green-200 bg-green-50 text-green-700"
                        : isCurrent
                          ? "border-blue-200 bg-blue-50 text-blue-700"
                          : "border-gray-200 bg-gray-50 text-gray-500"
                    }`}
                  >
                    <div className="truncate">{phase.label.replace(/Phase \d: /, "")}</div>
                  </div>
                );
              })}
            </div>

            {currentBoard && status === "running" && (
              <p className="mb-2 text-sm font-medium text-gray-800">
                Migrating: <span className="text-blue-700">{currentBoard}</span>
              </p>
            )}

            {currentTable && status === "running" && (
              <p className="mb-3 text-sm text-gray-600">
                Current: <code className="rounded bg-gray-100 px-1.5 py-0.5 text-xs">{currentTable}</code>
              </p>
            )}

            {status === "complete" && (
              <p className="text-sm font-medium text-green-700">
                Total documents written: {totalDocs}
              </p>
            )}
          </div>
        )}

        {/* Log Panel */}
        {logs.length > 0 && (
          <div className="rounded-xl border border-gray-200 bg-white shadow-sm">
            <div className="border-b border-gray-100 px-5 py-3">
              <h2 className="text-sm font-semibold uppercase tracking-wide text-gray-600">Log ({logs.length})</h2>
            </div>
            <div ref={logContainerRef} className="max-h-80 overflow-y-auto p-4 font-mono text-xs">
              {logs.map((l, i) => (
                <div
                  key={i}
                  className={`flex gap-2 py-0.5 ${
                    l.level === "error" ? "text-red-600" :
                    l.level === "warn" ? "text-amber-600" :
                    l.level === "success" ? "text-green-600" :
                    "text-gray-600"
                  }`}
                >
                  <span className="shrink-0 text-gray-400">{new Date(l.timestamp).toLocaleTimeString()}</span>
                  <span>{l.message}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
