import { useEffect, useMemo, useState } from "react";
import { useParams } from "react-router-dom";
import { AlertTriangle, BookOpen, Globe, Lightbulb, Link2, Quote, TrendingUp } from "lucide-react";
import { listGeoProbesV2, subscribeBoard, subscribeInsights } from "../../../db/boards";
import type { Board, GeoProbeV2Doc, InsightDoc } from "../../../db/collections";
import { MetricCard } from "../../../components/shared/MetricCard";
import { EmptyState } from "../../../components/shared/EmptyState";
import { InsightSection } from "../../../components/shared/InsightSection";
import { DataQualityBadge } from "../../../components/shared/DataQualityBadge";
import { OpenInsightsList } from "../../../components/shared/OpenInsightsList";

interface DomainRank {
  domain: string;
  count: number;
  engines: Set<string>;
  hasOurDomain: boolean;
}

export function CitationSourcesInsight() {
  const { id } = useParams<{ id: string }>();
  const [probes, setProbes] = useState<Array<GeoProbeV2Doc & { id: string }>>([]);
  const [board, setBoard] = useState<Board | null>(null);
  const [liveInsights, setLiveInsights] = useState<InsightDoc[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    const unsubBoard = subscribeBoard(id, setBoard);
    const unsubIns = subscribeInsights(id, setLiveInsights, { type: "trust_signal" });
    listGeoProbesV2(id)
      .then((p) => setProbes(p))
      .catch(() => setProbes([]))
      .finally(() => setLoading(false));
    return () => {
      unsubBoard();
      unsubIns();
    };
  }, [id]);

  const ownHost = useMemo(() => extractHost(board?.domain || ""), [board?.domain]);

  const { domainRanks, totalCitations, uniqueDomains, ownDomainCount } = useMemo(() => {
    const map = new Map<string, DomainRank>();
    let total = 0;
    let own = 0;

    for (const probe of probes) {
      const references = Array.isArray(probe.references) ? probe.references : [];
      const engine = String(probe.engine ?? "");
      for (const ref of references) {
        if (!ref) continue;
        total += 1;
        const domain = extractHost(String(ref));
        if (!domain) continue;
        const isOwn = ownHost.length > 0 && domain === ownHost;
        if (isOwn) own += 1;
        const entry = map.get(domain) ?? {
          domain,
          count: 0,
          engines: new Set<string>(),
          hasOurDomain: false,
        };
        entry.count += 1;
        if (engine) entry.engines.add(engine);
        if (isOwn) entry.hasOurDomain = true;
        map.set(domain, entry);
      }
    }

    const ranks = Array.from(map.values()).sort((a, b) => b.count - a.count);
    return {
      domainRanks: ranks,
      totalCitations: total,
      uniqueDomains: map.size,
      ownDomainCount: own,
    };
  }, [probes, ownHost]);

  const topDomains = domainRanks.slice(0, 20);
  const maxCount = topDomains[0]?.count ?? 1;

  const enginesSeen = useMemo(() => {
    const s = new Set<string>();
    for (const r of domainRanks) {
      for (const e of r.engines) s.add(e);
    }
    return s;
  }, [domainRanks]);

  const engineBreakdown = useMemo(() => {
    const map = new Map<string, number>();
    for (const probe of probes) {
      const refs = Array.isArray(probe.references) ? probe.references : [];
      const engine = String(probe.engine ?? "unknown");
      map.set(engine, (map.get(engine) ?? 0) + refs.length);
    }
    return Array.from(map.entries())
      .map(([engine, count]) => ({ engine, count }))
      .sort((a, b) => b.count - a.count);
  }, [probes]);

  const diagnosis = useMemo(() => {
    const items: Array<{ severity: "high" | "medium" | "low"; title: string; detail: string }> = [];
    if (probes.length === 0) {
      items.push({ severity: "medium", title: "No probe data", detail: "Run GEO Probe to collect citation sources." });
      return items;
    }
    if (totalCitations === 0) {
      items.push({ severity: "high", title: "No citations captured", detail: "AI engine responses did not include references." });
    }
    if (ownDomainCount === 0 && totalCitations > 0) {
      items.push({ severity: "high", title: "Your domain is not cited", detail: "None of the AI responses reference your site. Improve authority and entity signals." });
    }
    if (uniqueDomains > 0 && uniqueDomains < 5) {
      items.push({ severity: "medium", title: "Citation diversity low", detail: `Only ${uniqueDomains} unique domains cited. AI engines rely on a small pool for your topics.` });
    }
    return items;
  }, [probes.length, totalCitations, ownDomainCount, uniqueDomains]);

  const dataQuality = useMemo(() => {
    const signals = [
      { name: "GEO probes", ok: probes.length > 0 },
      { name: "Citations captured", ok: totalCitations > 0 },
      { name: "Engine coverage", ok: enginesSeen.size >= 2 },
      { name: "Own-domain citations", ok: ownDomainCount > 0 },
    ];
    const okCount = signals.filter((s) => s.ok).length;
    const score = Math.round((okCount / signals.length) * 100);
    const status: "ok" | "warning" | "degraded" | "invalid" =
      score >= 80 ? "ok" : score >= 50 ? "warning" : score > 0 ? "degraded" : "invalid";
    const notes = signals.filter((s) => !s.ok).map((s) => `${s.name} not available`);
    return { score, status, notes };
  }, [probes.length, totalCitations, enginesSeen.size, ownDomainCount]);

  if (loading) {
    return (
      <div className="flex min-h-[30vh] items-center justify-center text-sm text-[var(--shell-text-muted)]">
        불러오는 중...
      </div>
    );
  }

  if (probes.length === 0) {
    return (
      <EmptyState
        icon={Quote}
        title="No citation data yet"
        description="GEO Probe를 실행하면 AI 엔진이 브랜드 관련 답변 시 어떤 출처를 참고하는지 수집할 수 있습니다."
      />
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <MetricCard icon={Quote} label="Total Citations" value={String(totalCitations)} color="text-blue-600" />
        <MetricCard icon={Globe} label="Unique Domains" value={String(uniqueDomains)} color="text-teal-600" />
        <MetricCard icon={Link2} label="Own-domain Citations" value={String(ownDomainCount)} color="text-emerald-600" />
        <MetricCard icon={TrendingUp} label="Engines" value={String(enginesSeen.size)} color="text-cyan-600" />
      </div>

      <DataQualityBadge score={dataQuality.score} status={dataQuality.status} notes={dataQuality.notes} />

      <InsightSection title="Top Citation Domains" icon={BookOpen} count={topDomains.length} defaultOpen>
        {topDomains.length > 0 ? (
          <div className="space-y-2">
            {topDomains.map((d, i) => (
              <div key={d.domain} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <div className="flex items-center justify-between gap-3">
                  <div className="flex min-w-0 items-center gap-3">
                    <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-[var(--shell-panel)] text-[10px] font-semibold text-[var(--shell-text-muted)]">
                      {i + 1}
                    </span>
                    <div className="min-w-0">
                      <p className="truncate text-sm font-medium text-[var(--shell-text)]">
                        {d.domain}
                        {d.hasOurDomain && (
                          <span className="ml-2 rounded-full bg-emerald-500/10 px-1.5 py-0.5 text-[10px] font-medium text-emerald-600">
                            Yours
                          </span>
                        )}
                      </p>
                      <p className="mt-0.5 text-[11px] text-[var(--shell-text-muted)]">
                        {Array.from(d.engines).join(" · ") || "—"}
                      </p>
                    </div>
                  </div>
                  <span className="text-sm font-semibold text-[var(--shell-text)]">{d.count}</span>
                </div>
                <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[var(--shell-panel)]">
                  <div
                    className={`h-full ${d.hasOurDomain ? "bg-emerald-500" : "bg-blue-500"}`}
                    style={{ width: `${(d.count / maxCount) * 100}%` }}
                  />
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-[var(--shell-text-muted)]">No citation domains captured.</p>
        )}
      </InsightSection>

      {engineBreakdown.length > 0 && (
        <InsightSection title="Citations by Engine" icon={TrendingUp} count={engineBreakdown.length} defaultOpen={false}>
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {engineBreakdown.map((e) => (
              <div key={e.engine} className="flex items-center justify-between rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <span className="text-sm font-medium capitalize text-[var(--shell-text)]">{e.engine}</span>
                <span className="text-sm font-semibold text-[var(--shell-text)]">{e.count}</span>
              </div>
            ))}
          </div>
        </InsightSection>
      )}

      <InsightSection
        title="Open Insights"
        icon={Lightbulb}
        count={liveInsights.filter((i) => i.status !== "resolved" && i.status !== "ignored").length}
        defaultOpen
      >
        <OpenInsightsList insights={liveInsights} />
      </InsightSection>

      <InsightSection title="Diagnosis" icon={AlertTriangle} count={diagnosis.length} defaultOpen={diagnosis.length > 0}>
        {diagnosis.length > 0 ? (
          <div className="space-y-2">
            {diagnosis.map((item, i) => (
              <div key={i} className="flex items-start gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-3">
                <SeverityDot severity={item.severity} />
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-medium text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-xs text-[var(--shell-text-muted)]">{item.detail}</p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-sm text-emerald-600">Citation footprint looks healthy.</p>
        )}
      </InsightSection>
    </div>
  );
}

function SeverityDot({ severity }: { severity: "high" | "medium" | "low" }) {
  const color = severity === "high" ? "bg-rose-500" : severity === "medium" ? "bg-amber-500" : "bg-blue-500";
  return <span className={`mt-1.5 inline-block h-2 w-2 shrink-0 rounded-full ${color}`} />;
}

function extractHost(url: string): string {
  try {
    const u = new URL(url.startsWith("http") ? url : `https://${url}`);
    return u.hostname.replace(/^www\./, "");
  } catch {
    return url.replace(/^https?:\/\//, "").split("/")[0].replace(/^www\./, "");
  }
}
