import { useState } from "react";
import { useParams } from "react-router-dom";
import { useTracking, useTrackingRaw } from "./dataHub";
import { TrendChart } from "./components";
import { HeaderV4DiagnosticButton } from "./V4DiagnosticPanel";
import { runTrackingDiagnostics } from "./diagnostics/trackingDiagnostics";

export function PortalV4WeeklyReport() {
  const { id } = useParams();
  const { data, isLoading } = useTracking(id || "");
  const [activeRunId, setActiveRunId] = useState<string | null>(null);

  if (isLoading || !data) {
    return <div className="flex h-64 items-center justify-center text-[var(--shell-text-soft)]">로딩 중...</div>;
  }

  const rounds = data.rounds;
  const selectedRunId = activeRunId || rounds[rounds.length - 1]?.runId;
  const selectedIdx = rounds.findIndex((r) => r.runId === selectedRunId);
  const current = rounds[selectedIdx];
  const prev = selectedIdx > 0 ? rounds[selectedIdx - 1] : null;

  return (
    <>
      {id && <HeaderV4DiagnosticButton boardId={id} title="V4 WeeklyReport 진단" runner={runTrackingDiagnostics} />}
      <div className="mx-auto max-w-5xl space-y-6 p-6">
      {/* Topbar */}
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="text-xs font-semibold uppercase tracking-wider text-[var(--shell-accent)]">검증·변화 추적</div>
          <h1 className="mt-1 text-xl font-extrabold text-[var(--shell-text)]">개선 전후 변화 추적</h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            측정 회차별 노출률·순위 변화를 확인하고 개선 과제 진행 상태를 관리합니다.
          </p>
        </div>
        <div className="flex flex-col items-end gap-1 text-right">
          <div className="text-xs text-[var(--shell-text-soft)]">측정 기간 2025.05.15 – 2025.06.26</div>
        </div>
      </div>

      {/* 측정 회차 탭 */}
      <div className="flex flex-wrap gap-2">
        {rounds.map((r, i) => {
          const isActive = r.runId === selectedRunId;
          return (
            <button
              key={r.runId}
              onClick={() => setActiveRunId(r.runId)}
              className={`flex flex-col items-center rounded-lg px-4 py-2 text-xs transition-colors ${
                isActive
                  ? "bg-[var(--shell-accent)] text-white"
                  : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] hover:bg-white/10"
              }`}
            >
              <span className="font-bold">{i + 1}차 측정</span>
              <span className={`text-[10px] ${isActive ? "text-white/70" : "text-[var(--shell-text-soft)]"}`}>
                {r.date.slice(0, 10).replace(/-/g, ".")}
              </span>
            </button>
          );
        })}
      </div>

      {/* 회차별 KPI 카드 */}
      {current && (
        <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
          {[
            { label: "자사 언급률 (통합)", value: `${current.brandRate.toFixed(1)}%`, delta: prev ? current.brandRate - prev.brandRate : null, color: current.brandRate > 2 ? "text-amber-400" : "text-red-400" },
            { label: "ChatGPT 언급률", value: `${current.gptRate.toFixed(1)}%`, delta: prev ? current.gptRate - prev.gptRate : null, color: current.gptRate > 0 ? "text-emerald-400" : "text-red-400" },
            { label: "Gemini 언급률", value: `${current.geminiRate.toFixed(1)}%`, delta: prev ? current.geminiRate - prev.geminiRate : null, color: current.geminiRate > 0 ? "text-emerald-400" : "text-red-400" },
            { label: "총 답변 수", value: `${current.totalCalls}건`, delta: null, color: "text-[var(--shell-accent)]" },
          ].map((kpi) => (
            <div key={kpi.label} className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4">
              <div className="text-[11px] text-[var(--shell-text-soft)]">{kpi.label}</div>
              <div className={`mt-1 text-lg font-extrabold ${kpi.color}`}>{kpi.value}</div>
              {kpi.delta !== null && (
                <div className={`mt-0.5 text-[11px] font-semibold ${kpi.delta > 0 ? "text-emerald-400" : kpi.delta < 0 ? "text-rose-400" : "text-[var(--shell-text-soft)]"}`}>
                  {kpi.delta > 0 ? "+" : ""}{kpi.delta.toFixed(1)}%p vs 이전
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* 언급률 추이 차트 */}
      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">측정 회차별 언급률은 어떻게 변화했나요?</span>
          <span className="text-[11px] text-[var(--shell-text-soft)]">현재 {selectedIdx + 1}차 선택</span>
        </div>
        <div className="p-5">
          <TrendChart
            points={rounds.map((r) => ({
              date: r.date,
              brandRate: r.brandRate,
              gptRate: r.gptRate,
              geminiRate: r.geminiRate,
            }))}
          />
        </div>
      </article>

      {/* 쿼리별 회차 비교 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">쿼리별 회차 비교</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">각 질문에서 회차별 언급률 변화를 추적합니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] overflow-hidden">
        {/* <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">쿼리별 회차별 언급률 변화</span>
          <span className="text-[11px] text-[var(--shell-text-soft)]">{rounds.length}회차 측정</span>
        </div> */}
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                <th className="px-4 py-3">#</th>
                <th className="px-4 py-3">쿼리</th>
                {rounds.map((r, i) => (
                  <th key={r.runId} className="px-4 py-3 text-right">
                    <div>{i + 1}차</div>
                    <div className="text-[10px] font-normal text-[var(--shell-text-soft)]">{r.date.slice(0, 10).slice(5).replace("-", "/")}</div>
                  </th>
                ))}
                <th className="px-4 py-3 text-right">추세</th>
              </tr>
            </thead>
            <tbody>
              {data.queryRoundTable.map((row, qi) => {
                const rateMap = new Map(row.rates.map((r) => [r.runId, r.rate]));
                const rateValues = rounds.map((rd) => rateMap.get(rd.runId) ?? null);
                const validRates = rateValues.filter((v): v is number => v !== null);
                const first = validRates[0] ?? 0;
                const last = validRates[validRates.length - 1] ?? 0;
                const trend = last > first ? "\u2191" : last < first ? "\u2193" : "\u2014";
                const trendColor = last > first ? "text-emerald-400" : last < first ? "text-rose-400" : "text-[var(--shell-text-soft)]";
                return (
                  <tr key={row.queryText} className="border-b border-[var(--shell-border)]">
                    <td className="px-4 py-2.5 text-[var(--shell-text-soft)]">Q{qi + 1}</td>
                    <td className="max-w-[180px] truncate px-4 py-2.5 text-[var(--shell-text)]">{row.queryText}</td>
                    {rounds.map((rd) => {
                      const rate = rateMap.get(rd.runId);
                      return (
                        <td
                          key={rd.runId}
                          className={`px-4 py-2.5 text-right font-semibold ${
                            rate != null && rate >= 10 ? "text-emerald-400" : rate != null && rate > 0 ? "text-amber-400" : "text-[var(--shell-text-soft)]"
                          }`}
                        >
                          {rate != null ? (rate > 0 ? `${rate.toFixed(0)}%` : "0%") : "\u2014"}
                        </td>
                      );
                    })}
                    <td className={`px-4 py-2.5 text-right font-bold text-base ${trendColor}`}>{trend}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </article>

      {/* 변화 측정 기준 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">변화 측정 기준</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">개선 작업 전후 무엇이 달라졌는지 확인하는 기준입니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-[var(--shell-border)] text-[var(--shell-text-muted)]">
                <th className="px-4 py-3">추적 항목</th>
                <th className="px-4 py-3 text-right">현재 기준</th>
                <th className="px-4 py-3">확인할 변화</th>
              </tr>
            </thead>
            <tbody>
              {data.changeCriteria.map((c) => (
                <tr key={c.metric} className="border-b border-[var(--shell-border)]">
                  <td className="px-4 py-3 text-[var(--shell-text)]">{c.metric}</td>
                  <td className={`px-4 py-3 text-right font-semibold ${c.after < 2 ? "text-red-400" : "text-amber-400"}`}>
                    {typeof c.after === "number" && c.after < 10 ? c.after.toFixed(1) : c.after}
                    {c.metric.includes("률") ? "%" : ""}
                  </td>
                  <td className="px-4 py-3 text-[var(--shell-text-muted)]">
                    목표: {c.delta > 0 ? `+${c.delta.toFixed(1)}` : "개선"} 이상 달성
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </article>

      {/* 실행 항목 추적 */}
      <div className="border-t border-[var(--shell-border)] pt-6">
        <h2 className="text-sm font-bold text-[var(--shell-text)]">실행 항목 추적</h2>
        <p className="mt-0.5 text-xs text-[var(--shell-text-soft)]">개선 과제별 진행 상태입니다.</p>
      </div>

      <article className="rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-strong)] overflow-hidden">
        <div className="flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-5 py-3">
          <span className="text-xs font-medium text-[var(--shell-text)]">실행 항목 진행 현황</span>
        </div>
        <div className="divide-y divide-[var(--shell-border)]">
          {data.executionItems.map((item) => {
            const statusColor =
              item.status === "진행 중" ? "bg-emerald-500/20 text-emerald-400 border-emerald-400/30"
              : item.status === "작성 필요" ? "bg-rose-500/20 text-rose-400 border-rose-400/30"
              : item.status === "검토 필요" ? "bg-amber-500/20 text-amber-400 border-amber-400/30"
              : "bg-[var(--shell-panel-soft)] text-[var(--shell-text-muted)] border-gray-500/30";
            return (
              <div key={item.title} className="flex items-center justify-between gap-3 px-5 py-3.5">
                <div>
                  <p className="text-xs font-bold text-[var(--shell-text)]">{item.title}</p>
                  <p className="mt-0.5 text-[11px] text-[var(--shell-text-soft)]">{item.category}</p>
                </div>
                <span className={`shrink-0 rounded-full border px-2.5 py-0.5 text-[10px] font-bold ${statusColor}`}>
                  {item.status}
                </span>
              </div>
            );
          })}
        </div>
      </article>

      {import.meta.env.DEV && id && <TrackingDataInspector boardId={id} data={data} />}
    </div>
    </>
  );
}

function TrackingDataInspector({ boardId, data }: { boardId: string; data: import("./dataHub").TrackingData }) {
  const [open, setOpen] = useState(false);
  const { data: raw } = useTrackingRaw(boardId);

  if (!open) {
    return (
      <div className="border-t border-amber-500/30 pt-4 mt-6">
        <button
          onClick={() => setOpen(true)}
          className="rounded-lg border border-amber-500/40 bg-amber-500/10 px-3 py-2 text-[11px] font-medium text-amber-300 hover:bg-amber-500/20"
        >
          [DEV] Tracking Data Inspector
        </button>
      </div>
    );
  }

  const completedRuns = (raw?.completedRuns ?? []) as any[];
  const perRunAnalyses = raw?.perRunAnalyses ?? {};
  const perRunResults = raw?.perRunResults ?? {};

  return (
    <div className="border-t border-amber-500/30 pt-4 mt-6 space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-xs font-bold text-amber-300">[DEV] Tracking Data Inspector</h3>
        <button onClick={() => setOpen(false)} className="text-[10px] text-amber-300/60 hover:text-amber-300">Close</button>
      </div>

      {/* Raw Runs from Firestore */}
      <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-3">
        <h4 className="text-[11px] font-bold text-amber-200 mb-2">1. Firestore completedRuns (sorted by completedAt)</h4>
        <div className="overflow-x-auto">
          <table className="w-full text-[10px] text-left">
            <thead>
              <tr className="text-amber-300/70">
                <th className="pr-2 pb-1">#</th>
                <th className="pr-2 pb-1">runId</th>
                <th className="pr-2 pb-1">startedAt</th>
                <th className="pr-2 pb-1">completedAt</th>
                <th className="pr-2 pb-1">status</th>
                <th className="pr-2 pb-1">analysis?</th>
                <th className="pr-2 pb-1">results#</th>
              </tr>
            </thead>
            <tbody>
              {completedRuns.map((run: any, i: number) => {
                const startedAt = run.startedAt instanceof Date ? run.startedAt.toISOString() : String(run.startedAt ?? "");
                const completedAt = run.completedAt instanceof Date ? run.completedAt.toISOString() : String(run.completedAt ?? "");
                const hasAnalysis = run.id in perRunAnalyses;
                const resultCount = perRunResults[run.id]?.length ?? 0;
                return (
                  <tr key={run.id} className="text-[var(--shell-text-muted)] border-t border-amber-500/10">
                    <td className="pr-2 py-1 text-amber-300">{i + 1}</td>
                    <td className="pr-2 py-1 font-mono">{run.id?.slice(0, 12)}...</td>
                    <td className="pr-2 py-1">{startedAt.slice(0, 19)}</td>
                    <td className="pr-2 py-1 font-bold text-white">{completedAt.slice(0, 19)}</td>
                    <td className="pr-2 py-1">{run.status}</td>
                    <td className="pr-2 py-1">{hasAnalysis ? "Y" : <span className="text-red-400">N</span>}</td>
                    <td className="pr-2 py-1">{resultCount > 0 ? resultCount : <span className="text-red-400">0</span>}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Transformed Rounds */}
      <div className="rounded-lg border border-sky-500/30 bg-sky-500/5 p-3">
        <h4 className="text-[11px] font-bold text-sky-200 mb-2">2. Transformed rounds (displayed as column headers)</h4>
        <div className="overflow-x-auto">
          <table className="w-full text-[10px] text-left">
            <thead>
              <tr className="text-sky-300/70">
                <th className="pr-2 pb-1">col#</th>
                <th className="pr-2 pb-1">runId</th>
                <th className="pr-2 pb-1">date (header)</th>
                <th className="pr-2 pb-1">brandRate</th>
                <th className="pr-2 pb-1">gptRate</th>
                <th className="pr-2 pb-1">geminiRate</th>
              </tr>
            </thead>
            <tbody>
              {data.rounds.map((r, i) => (
                <tr key={r.runId} className="text-[var(--shell-text-muted)] border-t border-sky-500/10">
                  <td className="pr-2 py-1 text-sky-300">{i + 1}차</td>
                  <td className="pr-2 py-1 font-mono">{r.runId.slice(0, 12)}...</td>
                  <td className="pr-2 py-1 font-bold text-white">{r.date.slice(0, 19)}</td>
                  <td className="pr-2 py-1">{r.brandRate.toFixed(1)}%</td>
                  <td className="pr-2 py-1">{r.gptRate.toFixed(1)}%</td>
                  <td className="pr-2 py-1">{r.geminiRate.toFixed(1)}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* QueryRoundTable rate alignment */}
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-3">
        <h4 className="text-[11px] font-bold text-emerald-200 mb-2">3. queryRoundTable[0].rates alignment check</h4>
        {data.queryRoundTable.length > 0 ? (
          <div className="space-y-2">
            <div className="text-[10px] text-[var(--shell-text-muted)]">
              Query: "{data.queryRoundTable[0].queryText}"
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-[10px] text-left">
                <thead>
                  <tr className="text-emerald-300/70">
                    <th className="pr-2 pb-1">rate idx</th>
                    <th className="pr-2 pb-1">runId</th>
                    <th className="pr-2 pb-1">rate</th>
                    <th className="pr-2 pb-1">matches round[i]?</th>
                  </tr>
                </thead>
                <tbody>
                  {data.queryRoundTable[0].rates.map((r, i) => {
                    const roundAtI = data.rounds[i];
                    const matches = roundAtI?.runId === r.runId;
                    return (
                      <tr key={r.runId} className="text-[var(--shell-text-muted)] border-t border-emerald-500/10">
                        <td className="pr-2 py-1 text-emerald-300">{i}</td>
                        <td className="pr-2 py-1 font-mono">{r.runId.slice(0, 12)}...</td>
                        <td className="pr-2 py-1">{r.rate}%</td>
                        <td className={`pr-2 py-1 font-bold ${matches ? "text-emerald-400" : "text-red-400"}`}>
                          {matches ? "Y" : `N (round[${i}]=${roundAtI?.runId?.slice(0, 8) ?? "none"})`}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="text-[10px] text-[var(--shell-text-muted)]">queryRoundTable is empty</div>
        )}
      </div>

      {/* Object.keys order check */}
      <div className="rounded-lg border border-fuchsia-500/30 bg-fuchsia-500/5 p-3">
        <h4 className="text-[11px] font-bold text-fuchsia-200 mb-2">4. Object.keys(perRunResults) order (insertion order from Promise.all)</h4>
        <div className="text-[10px] text-[var(--shell-text-muted)] font-mono space-y-0.5">
          {Object.keys(perRunResults).map((rid, i) => {
            const matchesRound = data.rounds[i]?.runId === rid;
            return (
              <div key={rid} className={matchesRound ? "" : "text-red-400"}>
                [{i}] {rid.slice(0, 16)}... {matchesRound ? "" : ` (MISMATCH: round[${i}] = ${data.rounds[i]?.runId?.slice(0, 12) ?? "?"})`}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
