import { getDoc, getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths, SUMMARY_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runDiagnosisDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // 1. summaries/measurement (latest run info)
  let latestRunId: string | null = null;
  try {
    const snap = await getDoc(paths.summary(boardId, SUMMARY_KEYS.measurement));
    if (!snap.exists()) {
      results.push({ id: "diag-meas", label: "summaries/measurement", status: "fail", detail: "문서 없음" });
    } else {
      const d = snap.data() as any;
      latestRunId = d?.run?.id ?? null;
      results.push({ id: "diag-meas", label: "summaries/measurement", status: "pass", detail: `run.id: ${latestRunId ?? "N/A"}, status: ${d?.run?.status ?? "N/A"}` });
    }
  } catch (err: any) {
    results.push({ id: "diag-meas", label: "summaries/measurement", status: "fail", detail: err.message });
  }

  // 2. analyses/v3/measurements/{runId}
  if (latestRunId) {
    try {
      const snap = await getDoc(paths.v3MeasurementAnalysis(boardId, latestRunId));
      if (!snap.exists()) {
        results.push({ id: "diag-analysis", label: `analyses/v3/measurements/${latestRunId}`, status: "fail", detail: "문서 없음" });
      } else {
        const d = snap.data() as any;
        const hasQuery = Array.isArray(d?.queryBreakdown) && d.queryBreakdown.length > 0;
        results.push({ id: "diag-analysis", label: `analyses/v3/measurements/${latestRunId}`, status: "pass", detail: `queryBreakdown: ${hasQuery ? d.queryBreakdown.length + "개" : "없음"}` });
      }
    } catch (err: any) {
      results.push({ id: "diag-analysis", label: `analyses/v3/measurements/${latestRunId}`, status: "fail", detail: err.message });
    }

    // 3. measurement results sub-collection
    try {
      const snap = await getDocs(query(paths.v3MeasurementResults(boardId, latestRunId), fbLimit(5)));
      results.push({ id: "diag-results", label: "measurement results", status: snap.docs.length > 0 ? "pass" : "warn", detail: `${snap.docs.length}개 결과 문서` });
    } catch (err: any) {
      results.push({ id: "diag-results", label: "measurement results", status: "warn", detail: `조회 실패 (sub-collection 없을 수 있음): ${err.message}` });
    }
  }

  // 4. runs collection
  try {
    const snap = await getDocs(query(paths.runs(boardId), fbLimit(10)));
    results.push({ id: "diag-runs", label: "runs 컬렉션", status: snap.docs.length > 0 ? "pass" : "fail", detail: `${snap.docs.length}개` });
  } catch (err: any) {
    results.push({ id: "diag-runs", label: "runs 컬렉션", status: "fail", detail: err.message });
  }

  return results;
};
