import { Component, type ReactNode } from "react";

interface Props {
  children: ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error("[ErrorBoundary]", error, info.componentStack);
  }

  render() {
    const { error } = this.state;
    if (!error) return this.props.children;

    return (
      <div className="flex min-h-screen items-center justify-center bg-[var(--shell-main)] p-6 text-[var(--shell-text)]">
        <div className="w-full max-w-lg rounded-2xl border border-[var(--shell-danger)] bg-[var(--shell-panel)] p-8">
          <h2 className="text-lg font-semibold text-[var(--shell-danger)]">
            Something went wrong
          </h2>
          <pre className="mt-4 max-h-48 overflow-auto whitespace-pre-wrap rounded-xl bg-[var(--shell-panel-strong)] p-4 text-sm text-[var(--shell-text-muted)]">
            {error.message}
          </pre>
          <button
            type="button"
            onClick={() => {
              this.setState({ error: null });
              window.location.reload();
            }}
            className="mt-6 rounded-xl bg-[var(--shell-accent)] px-5 py-2.5 text-sm font-medium text-white"
          >
            Reload
          </button>
        </div>
      </div>
    );
  }
}
