import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from "recharts";

interface TrendPoint {
  date: string;
  brandRate: number;
  gptRate: number;
  geminiRate: number;
}

interface TrendChartProps {
  points: TrendPoint[];
}

const formatDate = (d: string) => {
  const dt = new Date(d);
  return `${dt.getMonth() + 1}/${dt.getDate()}`;
};

export function TrendChart({ points }: TrendChartProps) {
  if (points.length < 2) {
    return <p className="py-8 text-center text-sm text-[var(--shell-text-soft)]">추이 데이터가 부족합니다.</p>;
  }

  const data = points.map((p) => ({
    name: formatDate(p.date),
    "자사 통합": p.brandRate,
    ChatGPT: p.gptRate,
    Gemini: p.geminiRate,
  }));

  return (
    <div className="h-64 w-full">
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data} margin={{ top: 8, right: 16, bottom: 8, left: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="var(--shell-border)" />
          <XAxis dataKey="name" tick={{ fill: "var(--shell-text-muted)", fontSize: 11 }} axisLine={false} tickLine={false} />
          <YAxis tick={{ fill: "var(--shell-text-muted)", fontSize: 11 }} axisLine={false} tickLine={false} unit="%" />
          <Tooltip
            contentStyle={{ background: "var(--shell-panel-strong)", border: "1px solid var(--shell-border)", borderRadius: 8 }}
            labelStyle={{ color: "var(--shell-text)" }}
          />
          <Legend wrapperStyle={{ fontSize: 12 }} />
          <Line type="monotone" dataKey="자사 통합" stroke="var(--shell-accent)" strokeWidth={2.5} dot={{ r: 4 }} />
          <Line type="monotone" dataKey="ChatGPT" stroke="var(--shell-positive)" strokeWidth={2} dot={{ r: 3 }} />
          <Line type="monotone" dataKey="Gemini" stroke="#7dd3fc" strokeWidth={2} dot={{ r: 3 }} />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}
