import { getDoc, getDocs, query, limit as fbLimit } from "firebase/firestore";
import { paths, ANALYSIS_KEYS } from "../../../db/paths";
import type { DiagnosticCheck, DiagnosticRunner } from "./types";

export const runImprovementDiagnostics: DiagnosticRunner = async (boardId) => {
  const results: DiagnosticCheck[] = [];

  // 1. actions/v3/recommendations
  try {
    const snap = await getDocs(query(paths.v3Recommendations(boardId), fbLimit(20)));
    results.push({ id: "imp-recs", label: "actions/v3/recommendations", status: snap.docs.length > 0 ? "pass" : "fail", detail: `${snap.docs.length}개 문서` });
  } catch (err: any) {
    results.push({ id: "imp-recs", label: "actions/v3/recommendations", status: "fail", detail: err.message });
  }

  // 2. analyses/ai-search
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.aiSearch));
    results.push({ id: "imp-aisearch", label: "analyses/ai-search", status: snap.exists() ? "pass" : "fail", detail: snap.exists() ? "존재" : "문서 없음" });
  } catch (err: any) {
    results.push({ id: "imp-aisearch", label: "analyses/ai-search", status: "fail", detail: err.message });
  }

  // 3. analyses/improvement-plan
  try {
    const snap = await getDoc(paths.analysis(boardId, ANALYSIS_KEYS.improvementPlan));
    if (!snap.exists()) {
      results.push({ id: "imp-plan", label: "analyses/improvement-plan", status: "fail", detail: "문서 없음" });
    } else {
      const d = snap.data() as any;
      const hasPhases = Array.isArray(d?.phases) && d.phases.length > 0;
      results.push({ id: "imp-plan", label: "analyses/improvement-plan", status: "pass", detail: `phases: ${hasPhases ? d.phases.length + "개" : "없음"}` });
    }
  } catch (err: any) {
    results.push({ id: "imp-plan", label: "analyses/improvement-plan", status: "fail", detail: err.message });
  }

  return results;
};
