import { useEffect, useState } from "react";
import { subscribeLatestRun } from "../db/boards";
import type { BoardStatus, RunDoc, StepName, StepStatus } from "../db/collections";

export type StepStatusMap = Partial<Record<StepName, StepStatus>>;

export type BoardPhase = "pending" | "crawling" | "analyzing" | "complete" | "failed";

/**
 * Derive a UI-friendly phase from board.status (lifecycle cache) plus the
 * current run.steps map. board.status is the final word for `complete` /
 * `failed` / `pending`; the crawl-vs-analyze distinction comes from steps.
 */
export function derivePhase(
  boardStatus: BoardStatus | undefined,
  steps: StepStatusMap,
): BoardPhase {
  if (boardStatus === "complete") return "complete";
  if (boardStatus === "failed") return "failed";
  if (!boardStatus || boardStatus === "pending") return "pending";
  const crawl = steps.crawl;
  if (!crawl || crawl === "idle" || crawl === "pending" || crawl === "running") return "crawling";
  if (crawl === "failed") return "failed";
  return "analyzing";
}

function deriveStepStatus(run: RunDoc | null): StepStatusMap {
  if (!run) return {};
  const out: StepStatusMap = {};
  const steps = run.steps ?? {};
  (Object.keys(steps) as StepName[]).forEach((key) => {
    const entry = steps[key];
    if (entry && entry.status) out[key] = entry.status;
  });
  return out;
}

/**
 * Subscribe to the most recent run for a board and expose a flat
 * `{ stepName: status }` map. Run document is the single source of
 * truth for step status (see geoOrchestratorService).
 */
export function useRunSteps(boardId: string | undefined): {
  run: RunDoc | null;
  steps: StepStatusMap;
} {
  const [run, setRun] = useState<RunDoc | null>(null);

  useEffect(() => {
    if (!boardId) {
      setRun(null);
      return;
    }
    return subscribeLatestRun(boardId, setRun);
  }, [boardId]);

  return { run, steps: deriveStepStatus(run) };
}
