import { Link, useParams } from "react-router-dom";

interface DataQualityBadgeProps {
  score: number;
  status: "ok" | "warning" | "degraded" | "invalid";
  runDate?: string;
  notes?: string[];
}

const STATUS_STYLES: Record<DataQualityBadgeProps["status"], { label: string; dot: string; bg: string }> = {
  ok:       { label: "OK",       dot: "bg-emerald-500", bg: "bg-emerald-500/10 text-emerald-600" },
  warning:  { label: "Warning",  dot: "bg-amber-500",   bg: "bg-amber-500/10 text-amber-600" },
  degraded: { label: "Degraded", dot: "bg-orange-500",  bg: "bg-orange-500/10 text-orange-600" },
  invalid:  { label: "Invalid",  dot: "bg-rose-500",    bg: "bg-rose-500/10 text-rose-600" },
};

export function DataQualityBadge({ score, status, runDate, notes }: DataQualityBadgeProps) {
  const { id } = useParams<{ id: string }>();
  const style = STATUS_STYLES[status];

  return (
    <div className="flex flex-wrap items-center gap-3 rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-4 py-2.5">
      <div className="flex items-center gap-1.5">
        <span className={`inline-block h-2 w-2 rounded-full ${style.dot}`} />
        <span className="text-xs font-medium text-[var(--shell-text-muted)]">Data Quality</span>
      </div>
      <span className={`rounded-md px-2 py-0.5 text-[10px] font-semibold ${style.bg}`}>
        {score}% {style.label}
      </span>
      {runDate && (
        <span className="text-[10px] text-[var(--shell-text-muted)]">Last run: {runDate}</span>
      )}
      {id && (
        <Link to={`/board/${id}/workspace/operations`} className="ml-auto text-[10px] text-[var(--shell-accent)] hover:underline">
          View Runs
        </Link>
      )}
      {notes && notes.length > 0 && (
        <div className="mt-1 w-full">
          {notes.map((note, i) => (
            <p key={i} className="text-[10px] text-[var(--shell-text-muted)]">{note}</p>
          ))}
        </div>
      )}
    </div>
  );
}
