import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { storage } from "../../config/firebase";

const MAX_FIRESTORE_FIELD_BYTES = 900_000;
const MAX_FIRESTORE_DOC_BYTES = 950_000;

export function getByteLength(str: string): number {
  return new TextEncoder().encode(str).length;
}

export function exceedsFieldLimit(value: unknown): boolean {
  if (typeof value !== "string") return false;
  return getByteLength(value) > MAX_FIRESTORE_FIELD_BYTES;
}

export interface StorageRef {
  _storageRef: true;
  url: string;
  path: string;
  originalBytes: number;
}

export function isStorageRef(val: unknown): val is StorageRef {
  return typeof val === "object" && val !== null && (val as any)._storageRef === true;
}

export async function uploadLargeField(
  boardId: string,
  docPath: string,
  fieldName: string,
  content: string,
): Promise<StorageRef> {
  const storagePath = `boards/${boardId}/migration-overflow/${docPath}/${fieldName}.txt`;
  const storageRef = ref(storage, storagePath);
  const bytes = new TextEncoder().encode(content);
  await uploadBytes(storageRef, bytes, { contentType: "text/plain; charset=utf-8" });
  const url = await getDownloadURL(storageRef);
  return {
    _storageRef: true,
    url,
    path: storagePath,
    originalBytes: bytes.length,
  };
}

function getDocByteLength(doc: Record<string, unknown>): number {
  return getByteLength(JSON.stringify(doc));
}

export async function offloadLargeFields(
  doc: Record<string, unknown>,
  boardId: string,
  docPath: string,
): Promise<Record<string, unknown>> {
  const result = { ...doc };

  // Phase 1: offload individual fields exceeding the per-field limit
  for (const key of Object.keys(result)) {
    if (exceedsFieldLimit(result[key])) {
      result[key] = await uploadLargeField(boardId, docPath, key, result[key] as string);
    }
  }

  // Phase 2: if total doc still exceeds the document limit, progressively offload largest string fields
  while (getDocByteLength(result) > MAX_FIRESTORE_DOC_BYTES) {
    let largestKey: string | null = null;
    let largestSize = 0;
    for (const key of Object.keys(result)) {
      if (typeof result[key] === "string") {
        const size = getByteLength(result[key] as string);
        if (size > largestSize) {
          largestSize = size;
          largestKey = key;
        }
      }
    }
    if (!largestKey) break;
    result[largestKey] = await uploadLargeField(boardId, docPath, largestKey, result[largestKey] as string);
  }

  return result;
}
