import { createContext, useContext, useRef, type RefObject } from "react";
import { Outlet } from "react-router-dom";
import { Moon, PanelLeftClose, PanelLeftOpen, Sun } from "lucide-react";
import { Sidebar } from "./Sidebar";
import { ErrorBoundary } from "./ErrorBoundary";
import { useShellPreferences } from "./ShellPreferences";

const HeaderSlotCtx = createContext<RefObject<HTMLDivElement> | null>(null);
export function useHeaderSlot() { return useContext(HeaderSlotCtx); }

export function BoardLayout() {
  const { sidebarCollapsed, theme, toggleSidebar, toggleTheme } = useShellPreferences();
  const slotRef = useRef<HTMLDivElement>(null!);

  return (
    <div className="shell-transition flex min-h-screen bg-[var(--shell-main)] text-[var(--shell-text)]">
      <Sidebar />
      <main className="shell-transition min-w-0 flex-1">
        <div
          className="sticky top-0 z-30 border-b border-[var(--shell-border)] backdrop-blur-xl"
          style={{ background: "color-mix(in srgb, var(--shell-main) 82%, transparent)" }}
        >
          <div className="flex items-center justify-between gap-3 px-4 py-3 sm:px-6">
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={toggleSidebar}
                className="shell-toggle shell-transition h-10 w-10"
                title={sidebarCollapsed ? "사이드바 펼치기" : "사이드바 접기"}
              >
                {sidebarCollapsed ? <PanelLeftOpen className="h-4 w-4" /> : <PanelLeftClose className="h-4 w-4" />}
              </button>
              <div className="hidden text-xs uppercase tracking-[0.22em] text-[var(--shell-text-soft)] sm:block">
                GEO Insight Workspace
              </div>
            </div>

            <div className="flex items-center gap-2">
              <div ref={slotRef} className="flex items-center gap-2" />
              <button
                type="button"
                onClick={toggleTheme}
                className="shell-toggle shell-transition flex h-10 items-center gap-2 px-3"
                title={theme === "dark" ? "밝은 UI로 전환" : "어두운 UI로 전환"}
              >
                {theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
                <span className="hidden text-sm sm:block">{theme === "dark" ? "Light UI" : "Dark UI"}</span>
              </button>
            </div>
          </div>
        </div>

        <div className="px-4 py-4 sm:px-6 sm:py-5">
          <ErrorBoundary>
            <HeaderSlotCtx.Provider value={slotRef}>
              <Outlet />
            </HeaderSlotCtx.Provider>
          </ErrorBoundary>
        </div>
      </main>
    </div>
  );
}
