import { useState, useCallback, useRef, useEffect } from "react";
import { createPortal } from "react-dom";
import { Bug, X, Loader2, CheckCircle2, XCircle, AlertTriangle, Database } from "lucide-react";
import { useQueryClient } from "@tanstack/react-query";
import { useHeaderSlot } from "../../components/BoardLayout";
import { seedPortalV4Data } from "../../db/seedPortalV4";
import type { DiagnosticCheck, DiagnosticRunner } from "./diagnostics/types";

interface V4DiagnosticButtonProps {
  boardId: string;
  title: string;
  runner: DiagnosticRunner;
}

export function V4DiagnosticButton({ boardId, title, runner }: V4DiagnosticButtonProps) {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [checks, setChecks] = useState<DiagnosticCheck[]>([]);
  const [seeding, setSeeding] = useState(false);
  const [seedResult, setSeedResult] = useState<string[] | null>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const queryClient = useQueryClient();

  const runDiagnostics = useCallback(async () => {
    setLoading(true);
    setChecks([]);
    try {
      const results = await runner(boardId);
      setChecks(results);
    } catch (err: any) {
      setChecks([{ id: "fatal", label: "진단 실행 실패", status: "fail", detail: err.message }]);
    }
    setLoading(false);
  }, [boardId, runner]);

  const handleSeed = useCallback(async () => {
    setSeeding(true);
    setSeedResult(null);
    try {
      const written = await seedPortalV4Data(boardId);
      setSeedResult(written);
      await queryClient.invalidateQueries({ queryKey: ["portalV4"] });
      await queryClient.invalidateQueries({ queryKey: ["v3-runs-50"] });
      runDiagnostics();
    } catch (err: any) {
      setSeedResult([`ERROR: ${err.message}`]);
    }
    setSeeding(false);
  }, [boardId, runDiagnostics, queryClient]);

  const handleOpen = () => {
    setOpen(true);
    runDiagnostics();
  };

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (
        panelRef.current && !panelRef.current.contains(e.target as Node) &&
        btnRef.current && !btnRef.current.contains(e.target as Node)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [open]);

  if (!import.meta.env.DEV) return null;

  return (
    <div className="relative">
      <button
        ref={btnRef}
        onClick={open ? () => setOpen(false) : handleOpen}
        className="flex items-center gap-1 rounded-lg border border-amber-500/40 bg-amber-500/10 px-2.5 py-1 text-[11px] font-medium text-amber-300 hover:bg-amber-500/20 transition-colors"
        title={title}
      >
        <Bug className="h-3.5 w-3.5" /> V4 진단
      </button>

      {open && (
        <div
          ref={panelRef}
          className="absolute right-0 top-full mt-2 z-[999] w-[420px] max-h-[70vh] overflow-y-auto rounded-xl border border-[var(--shell-border)] bg-[var(--shell-panel)] shadow-2xl"
        >
          <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[var(--shell-border)] bg-[var(--shell-panel)] px-4 py-3">
            <div className="min-w-0">
              <h2 className="text-sm font-semibold text-[var(--shell-text)] truncate">{title}</h2>
              <div className="text-[10px] text-[var(--shell-text-muted)] mt-0.5 truncate">boardId: {boardId}</div>
            </div>
            <div className="flex items-center gap-1.5 shrink-0">
              <button onClick={runDiagnostics} disabled={loading}
                className="rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-2.5 py-1 text-[10px] text-[var(--shell-text)] hover:bg-[var(--shell-border)] disabled:opacity-50 transition-colors">
                {loading ? "검사 중..." : "재검사"}
              </button>
              <button onClick={() => setOpen(false)} className="rounded-lg p-1 text-[var(--shell-text-muted)] hover:text-[var(--shell-text)] hover:bg-[var(--shell-panel-soft)] transition-colors">
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>

          <div className="p-3">
            {loading && (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="h-5 w-5 animate-spin text-[var(--shell-accent)]" />
                <span className="ml-2 text-xs text-[var(--shell-text-muted)]">Firestore 문서 검사 중...</span>
              </div>
            )}

            {!loading && checks.length > 0 && (
              <div className="space-y-1.5">
                {checks.map((c) => (
                  <div key={c.id} className={`rounded-lg border px-3 py-2 ${
                    c.status === "pass" ? "border-emerald-500/30 bg-emerald-500/5" :
                    c.status === "fail" ? "border-red-500/30 bg-red-500/5" :
                    c.status === "warn" ? "border-amber-500/30 bg-amber-500/5" :
                    "border-[var(--shell-border)] bg-[var(--shell-panel-soft)]"
                  }`}>
                    <div className="flex items-start gap-2">
                      <div className="mt-0.5 shrink-0">
                        {c.status === "pass" && <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400" />}
                        {c.status === "fail" && <XCircle className="h-3.5 w-3.5 text-red-400" />}
                        {c.status === "warn" && <AlertTriangle className="h-3.5 w-3.5 text-amber-400" />}
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="text-[11px] font-medium text-[var(--shell-text)]">{c.label}</div>
                        <div className="mt-0.5 text-[10px] text-[var(--shell-text-muted)] break-all">{c.detail}</div>
                      </div>
                    </div>
                  </div>
                ))}

                <div className="mt-3 rounded-lg border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] px-3 py-2">
                  <div className="flex gap-4 text-[10px]">
                    <span className="text-emerald-400">{checks.filter((c) => c.status === "pass").length} pass</span>
                    <span className="text-amber-400">{checks.filter((c) => c.status === "warn").length} warn</span>
                    <span className="text-red-400">{checks.filter((c) => c.status === "fail").length} fail</span>
                  </div>
                </div>
              </div>
            )}

            {/* Seed Section */}
            <div className="mt-3 border-t border-[var(--shell-border)] pt-3">
              <button
                onClick={handleSeed}
                disabled={seeding}
                className="flex w-full items-center justify-center gap-2 rounded-lg border border-sky-500/40 bg-sky-500/10 px-3 py-2 text-[11px] font-medium text-sky-300 hover:bg-sky-500/20 disabled:opacity-50 transition-colors"
              >
                {seeding ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Database className="h-3.5 w-3.5" />}
                {seeding ? "Seed 기록 중..." : "V4 Seed 기록"}
              </button>
              {seedResult && (
                <div className="mt-2 space-y-1">
                  {seedResult.map((item, i) => (
                    <div key={i} className={`rounded border px-2 py-1 text-[10px] ${
                      item.startsWith("ERROR") ? "border-red-500/30 bg-red-500/5 text-red-300" : "border-emerald-500/30 bg-emerald-500/5 text-emerald-300"
                    }`}>
                      {item.startsWith("ERROR") ? item : `[pass] ${item}`}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export function HeaderV4DiagnosticButton(props: V4DiagnosticButtonProps) {
  const slotRef = useHeaderSlot();
  const [mounted, setMounted] = useState(false);
  useEffect(() => { setMounted(true); }, []);
  if (!import.meta.env.DEV || !mounted || !slotRef?.current) return null;
  return createPortal(<V4DiagnosticButton {...props} />, slotRef.current);
}
