import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentType,
  type ReactNode,
} from "react";
import { NavLink, useParams, useLocation } from "react-router-dom";
import { ChevronDown, MoreHorizontal } from "lucide-react";

export interface TabDef {
  label: string;
  slug: string;
  icon: ComponentType<{ className?: string }>;
  overflow?: boolean;
  category?: string;
  sublabel?: string;
}

interface TabLayoutProps {
  title: string;
  description: string;
  tabs: TabDef[];
  basePath: string;
  children: ReactNode;
  actions?: ReactNode;
}

export function TabLayout({ title, description, tabs, basePath, children, actions }: TabLayoutProps) {
  const { id } = useParams<{ id: string }>();
  const { pathname } = useLocation();
  const base = `/board/${id}/${basePath}`;

  const pinnable = tabs.filter((t) => !t.overflow);
  const explicitOverflow = tabs.filter((t) => t.overflow);

  const navRef = useRef<HTMLElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const [visibleCount, setVisibleCount] = useState(pinnable.length);

  useLayoutEffect(() => {
    const nav = navRef.current;
    const measurer = measureRef.current;
    if (!nav || !measurer) return;

    const compute = () => {
      const navWidth = nav.clientWidth;
      const style = getComputedStyle(nav);
      const padLeft = parseFloat(style.paddingLeft) || 0;
      const padRight = parseFloat(style.paddingRight) || 0;
      const gap = parseFloat(style.columnGap || style.gap || "0") || 0;
      const available = navWidth - padLeft - padRight;

      const children = Array.from(measurer.children) as HTMLElement[];
      const widths = children.map((c) => c.offsetWidth);
      const moreW = widths[widths.length - 1] ?? 0;
      const tabWidths = widths.slice(0, pinnable.length);

      // Try fitting all tabs without a More button.
      const totalAllTabs = tabWidths.reduce((sum, w, i) => sum + w + (i > 0 ? gap : 0), 0);
      if (explicitOverflow.length === 0 && totalAllTabs <= available) {
        setVisibleCount(pinnable.length);
        return;
      }

      // Otherwise reserve space for the More button.
      const allowance = available - moreW - (pinnable.length > 0 ? gap : 0);
      let used = 0;
      let count = 0;
      for (let i = 0; i < tabWidths.length; i++) {
        const add = tabWidths[i] + (i > 0 ? gap : 0);
        if (used + add > allowance) break;
        used += add;
        count++;
      }
      // Reserve one extra slot as breathing room — always push one more tab into More.
      if (count > 0 && count < pinnable.length) count -= 1;
      setVisibleCount(Math.max(0, count));
    };

    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(nav);
    window.addEventListener("resize", compute);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", compute);
    };
  }, [pinnable.length, explicitOverflow.length, tabs]);

  const pinned = pinnable.slice(0, visibleCount);
  const autoOverflow = pinnable.slice(visibleCount);
  const overflowTabs = [...autoOverflow, ...explicitOverflow];
  const firstPinned = pinnable[0];
  const activeOverflowTab = overflowTabs.find((t) => pathname === `${base}/${t.slug}`);
  const showMore = overflowTabs.length > 0;

  return (
    <div className="mx-auto max-w-6xl space-y-6 p-6 lg:p-10">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight text-[var(--shell-text)]">
            {title}
          </h1>
          <p className="mt-1 text-sm text-[var(--shell-text-muted)]">
            {description}
          </p>
        </div>
        {actions}
      </div>

      <nav
        ref={navRef}
        className="relative flex flex-nowrap items-center gap-1 rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel-soft)] p-1.5"
      >
        {/* Hidden measurement row — identical styles to the real tabs and More button */}
        <div
          ref={measureRef}
          aria-hidden="true"
          className="pointer-events-none invisible absolute left-0 top-0 flex gap-1 p-1.5"
          style={{ visibility: "hidden" }}
        >
          {pinnable.map((tab) => {
            const Icon = tab.icon;
            return (
              <span
                key={`m-${tab.slug}`}
                className="flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium"
              >
                <Icon className="h-4 w-4" />
                {tab.label}
              </span>
            );
          })}
          <span className="flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium">
            <MoreHorizontal className="h-4 w-4" />
            More
            <ChevronDown className="h-3.5 w-3.5" />
          </span>
        </div>

        {pinned.map((tab) => {
          const href = `${base}/${tab.slug}`;
          const isActive =
            pathname === href ||
            (firstPinned && tab.slug === firstPinned.slug && pathname === base);
          const Icon = tab.icon;
          return (
            <NavLink
              key={tab.slug}
              to={href}
              className={`flex shrink-0 items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium transition-colors ${
                isActive
                  ? "bg-[var(--shell-panel)] text-[var(--shell-text)] shadow-sm"
                  : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
              }`}
            >
              <Icon className="h-4 w-4" />
              {tab.label}
            </NavLink>
          );
        })}

        {showMore && (
          <MoreMenu
            tabs={overflowTabs}
            base={base}
            activeOverflowTab={activeOverflowTab}
          />
        )}
      </nav>

      {children}
    </div>
  );
}

function MoreMenu({
  tabs,
  base,
  activeOverflowTab,
}: {
  tabs: TabDef[];
  base: string;
  activeOverflowTab?: TabDef;
}) {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onClick);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  useEffect(() => {
    setOpen(false);
  }, [activeOverflowTab?.slug]);

  const categories = new Map<string, TabDef[]>();
  for (const t of tabs) {
    const key = t.category ?? "Primary";
    const list = categories.get(key) ?? [];
    list.push(t);
    categories.set(key, list);
  }

  const isActive = !!activeOverflowTab;
  const ActiveIcon = activeOverflowTab?.icon;
  const categoryCount = categories.size;
  const gridCols =
    categoryCount >= 3 ? "sm:grid-cols-3" : categoryCount === 2 ? "sm:grid-cols-2" : "sm:grid-cols-1";

  return (
    <div ref={wrapRef} className="relative ml-auto shrink-0">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        className={`flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium transition-colors ${
          isActive
            ? "bg-[var(--shell-panel)] text-[var(--shell-text)] shadow-sm"
            : "text-[var(--shell-text-muted)] hover:text-[var(--shell-text)]"
        }`}
      >
        {ActiveIcon ? <ActiveIcon className="h-4 w-4" /> : <MoreHorizontal className="h-4 w-4" />}
        {activeOverflowTab?.label ?? "More"}
        <ChevronDown className={`h-3.5 w-3.5 transition-transform ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <div
          role="menu"
          className="absolute right-0 top-[calc(100%+6px)] z-30 w-[min(640px,calc(100vw-2rem))] rounded-2xl border border-[var(--shell-border)] bg-[var(--shell-panel)] p-4 shadow-lg"
        >
          <div className={`grid grid-cols-1 gap-3 ${gridCols}`}>
            {Array.from(categories.entries()).map(([category, items]) => (
              <div key={category}>
                <div className="px-2 py-1 text-[10px] font-semibold uppercase tracking-[0.18em] text-[var(--shell-text-muted)]">
                  {category}
                </div>
                {items.map((t) => {
                  const href = `${base}/${t.slug}`;
                  const active = activeOverflowTab?.slug === t.slug;
                  const Icon = t.icon;
                  return (
                    <NavLink
                      key={t.slug}
                      to={href}
                      role="menuitem"
                      onClick={() => setOpen(false)}
                      className={`flex w-full items-start gap-2 rounded-xl px-3 py-2.5 text-left transition-colors ${
                        active
                          ? "bg-[var(--shell-panel-soft)]"
                          : "hover:bg-[var(--shell-panel-soft)]"
                      }`}
                    >
                      <Icon className="mt-0.5 h-4 w-4 shrink-0 text-[var(--shell-text-muted)]" />
                      <div className="min-w-0">
                        <div className="text-sm font-semibold text-[var(--shell-text)]">
                          {t.label}
                        </div>
                        {t.sublabel && (
                          <div className="mt-0.5 text-xs text-[var(--shell-text-muted)]">
                            {t.sublabel}
                          </div>
                        )}
                      </div>
                    </NavLink>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export function useActiveTab(tabs: TabDef[], basePath: string): string {
  const { id, tab } = useParams<{ id: string; tab?: string }>();
  const { pathname } = useLocation();
  const base = `/board/${id}/${basePath}`;

  if (tab) return tab;
  for (const t of tabs) {
    if (pathname === `${base}/${t.slug}` || pathname.startsWith(`${base}/${t.slug}/`)) {
      return t.slug;
    }
  }
  return tabs[0]?.slug ?? "";
}
