import { useState } from "react";

interface LazyStorageTextProps {
  storageUrl: string;
  className?: string;
}

export function LazyStorageText({ storageUrl, className = "" }: LazyStorageTextProps) {
  const [state, setState] = useState<"idle" | "loading" | "loaded" | "error">("idle");
  const [text, setText] = useState("");

  async function handleExpand() {
    setState("loading");
    try {
      const res = await fetch(storageUrl);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const content = await res.text();
      setText(content);
      setState("loaded");
    } catch {
      setState("error");
    }
  }

  if (state === "idle") {
    return (
      <button
        onClick={handleExpand}
        className="inline-flex items-center gap-1 rounded border border-[var(--shell-accent)]/30 bg-[var(--shell-accent-soft)] px-2 py-1 text-[11px] font-semibold text-[var(--shell-accent)] transition-colors hover:bg-[var(--shell-accent)]/20"
      >
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" className="h-3 w-3">
          <path d="M6.22 8.72a.75.75 0 0 0 1.06 1.06l5.22-5.22v1.69a.75.75 0 0 0 1.5 0v-3.5a.75.75 0 0 0-.75-.75h-3.5a.75.75 0 0 0 0 1.5h1.69L6.22 8.72Z" />
          <path d="M3.5 6.75c0-.69.56-1.25 1.25-1.25H7A.75.75 0 0 0 7 4H4.75A2.75 2.75 0 0 0 2 6.75v4.5A2.75 2.75 0 0 0 4.75 14h4.5A2.75 2.75 0 0 0 12 11.25V9a.75.75 0 0 0-1.5 0v2.25c0 .69-.56 1.25-1.25 1.25h-4.5c-.69 0-1.25-.56-1.25-1.25v-4.5Z" />
        </svg>
        펼치기
      </button>
    );
  }

  if (state === "loading") {
    return (
      <span className="inline-flex items-center gap-1.5 text-[11px] text-[var(--shell-text-soft)]">
        <span className="h-3 w-3 animate-spin rounded-full border-2 border-[var(--shell-accent)] border-t-transparent" />
        불러오는 중...
      </span>
    );
  }

  if (state === "error") {
    return (
      <div className="space-y-1">
        <span className="text-[11px] text-rose-400">전문을 불러오지 못했습니다.</span>
        <button
          onClick={handleExpand}
          className="ml-2 text-[11px] font-semibold text-[var(--shell-accent)] underline"
        >
          재시도
        </button>
      </div>
    );
  }

  return (
    <div className={`space-y-1 ${className}`}>
      <div className="flex items-center justify-between">
        <span className="text-[10px] font-semibold text-[var(--shell-text-soft)]">전문 내용</span>
        <button
          onClick={() => { setState("idle"); setText(""); }}
          className="text-[10px] font-semibold text-[var(--shell-text-soft)] hover:text-[var(--shell-text)]"
        >
          접기
        </button>
      </div>
      <p className="whitespace-pre-wrap text-[11px] leading-relaxed text-[var(--shell-text)]">{text}</p>
    </div>
  );
}
