export type BoardStatus = "pending" | "processing" | "complete" | "failed";

/**
 * Legacy values (`crawling`, `analyzing`) are normalized to `processing` on
 * read. Kept only for documents written before the simplification.
 */
export type BoardStatusRaw = BoardStatus | "crawling" | "analyzing";

export function normalizeBoardStatus(raw: unknown): BoardStatus {
  if (raw === "complete" || raw === "failed" || raw === "pending") return raw;
  if (raw === "processing" || raw === "crawling" || raw === "analyzing") return "processing";
  return "pending";
}

