export function flatKeywords(kw: string[] | ClassifiedKeywords | null | undefined): string[] {
  if (!kw) return [];
  if (Array.isArray(kw)) return kw;
  const all: string[] = [];
  for (const cat of [kw.site, kw.competitor, kw.recommended, kw.local] as KeywordMetrics[][]) {
    if (cat) all.push(...cat.map((k) => k.keyword));
  }
  return all;
}

